insert into hab_tipos_prestador (codigo, nombre, definicion, condiciones, fuente_norma, fuente_articulo, fuente_pagina, fuente_url, orden) values
  ('ips', 'Institución Prestadora de Servicios de Salud (IPS)', 'Son las entidades cuyo objeto social es la prestación de servicios de salud y se encuentran inscritas y con servicios de salud habilitados de conformidad con el Sistema Obligatorio de Garantía de Calidad en Salud.', array['capacidad_tecnico_administrativa', 'suficiencia_patrimonial_financiera', 'capacidad_tecnologica_cientifica']::text[], 'Resolución 3100 de 2019 (MinSalud)', 'Manual num. 7.1; Art. 3 (texto Res. 544/2023)', 'pág. 30', 'https://www.minsalud.gov.co/sites/rid/Lists/BibliotecaDigital/RIDE/DE/DIJ/resolucion-3100-de-2019.pdf', 1),
  ('profesional_independiente', 'Profesional independiente de salud', 'Son todas las personas naturales egresadas de un programa de educación superior de ciencias de la salud de conformidad con la Ley 30 de 1992 o las normas que la modifiquen, adicionen o sustituyan, con facultades para actuar de manera autónoma en la prestación del servicio de salud, para lo cual podrán contar con personal de apoyo de los niveles de formación técnico y/o auxiliar.', array['capacidad_tecnologica_cientifica']::text[], 'Resolución 3100 de 2019 (MinSalud)', 'Manual num. 7.2; Art. 3 (texto Res. 544/2023)', 'págs. 30-31', 'https://www.minsalud.gov.co/sites/rid/Lists/BibliotecaDigital/RIDE/DE/DIJ/resolucion-3100-de-2019.pdf', 2),
  ('transporte_especial', 'Transporte especial de pacientes', 'Son los prestadores de servicios de salud que realizan traslado de pacientes en ambulancia y pueden realizar atención prehospitalaria.', array['capacidad_tecnico_administrativa', 'suficiencia_patrimonial_financiera', 'capacidad_tecnologica_cientifica']::text[], 'Resolución 3100 de 2019 (MinSalud)', 'Manual num. 7.4; Art. 3 (texto Res. 544/2023)', 'pág. 31', 'https://www.minsalud.gov.co/sites/rid/Lists/BibliotecaDigital/RIDE/DE/DIJ/resolucion-3100-de-2019.pdf', 3),
  ('objeto_social_diferente', 'Entidad con objeto social diferente', 'Con esta denominación se inscriben los prestadores de servicios de salud cuyo objeto social no es la prestación de servicios de salud y que por requerimientos propios de la actividad que realizan, brindan servicios de salud de baja y mediana complejidad de los grupos de consulta externa, apoyo diagnóstico y complementación terapéutica, y servicios de trasporte asistencial de pacientes, atención prehospitalaria y cuidado básico del consumo de sustancias psicoactivas, adicionalmente pueden realizar procedimientos exclusivamente de cirugía ambulatoria. No incluye la prestación del servicio de urgencias, servicio para la atención del parto y los servicios del grupo de internación. Los servicios habilitados no pueden ser ofrecidos en contratación dentro del Sistema General de Seguridad Social en Salud.', array['capacidad_tecnico_administrativa', 'capacidad_tecnologica_cientifica']::text[], 'Resolución 3100 de 2019 (MinSalud)', 'Manual num. 7.3; num. 8.1.1 (no se le exige sistema contable ni suficiencia); Art. 3 (texto Res. 544/2023)', 'págs. 31-32', 'https://www.minsalud.gov.co/sites/rid/Lists/BibliotecaDigital/RIDE/DE/DIJ/resolucion-3100-de-2019.pdf', 4)
insert into hab_documentos_catalogo (id, norma_id, codigo, nombre_corto, descripcion_literal, explicacion_sencilla, aplica_a, obligatorio, condicion_texto, condiciones, seccion, por_sede, tiene_vencimiento, regla_vigencia, uno_por_servicio, fuente_norma, fuente_articulo, fuente_pagina, fuente_url, verificado, orden) values
  ('86d05c35-57d6-5585-8811-3b5394f16bd1', '66cba8a9-8597-53d6-94a8-5fdacb81ba7d', 'formulario_inscripcion_reps', 'Formulario de inscripción REPS (impreso)', 'Art. 7 (texto vigente, Res. 465/2025): 7.1.3 Diligenciar el formulario de inscripción en el REPS. 7.1.5 Imprimir el formulario de inscripción. 7.2 Radicar el formulario de inscripción y el documento de declaración de la autoevaluación del cumplimiento de las condiciones de habilitación ante la secretaría de salud departamental o distrital, o la entidad que tenga a cargo dichas competencias, y los demás soportes definidos en el Manual de Inscripción de Prestadores y Habilitación de Servicios de Salud.', null, array['ips', 'profesional_independiente', 'transporte_especial', 'objeto_social_diferente']::text[], true, null, '{}'::text[], 'radicar', false, false, null, false, 'Resolución 465 de 2025 (MinSalud), modifica Res. 3100/2019', 'Art. 3 (modifica Art. 7 de la Res. 3100), num. 7.1.3, 7.1.5 y 7.2; ver también Manual num. 9.1.2 lit. b (Res. 3100, pág. 37)', 'Res. 465: hojas 3-4', 'https://www.minsalud.gov.co/sites/rid/Lists/BibliotecaDigital/RIDE/DE/DIJ/resolucion-0465-de-2025.pdf', true, 1),
  ('2c15da8e-80f6-5002-928b-4169de1ba4b8', '66cba8a9-8597-53d6-94a8-5fdacb81ba7d', 'declaracion_autoevaluacion', 'Declaración de autoevaluación generada por el REPS', 'a. Documento de la declaración de la autoevaluación del cumplimiento de las condiciones de habilitación generado por el REPS.', null, array['ips', 'profesional_independiente', 'transporte_especial', 'objeto_social_diferente']::text[], true, 'Una declaración por cada servicio a ofertar (Art. 7.1.4).', '{}'::text[], 'radicar', false, false, null, true, 'Resolución 3100 de 2019 (MinSalud)', 'Manual num. 9.1.3 lit. a; Art. 7.1.4 y 7.2', 'pág. 37 (manual); págs. 4 (Art. 7)', 'https://www.minsalud.gov.co/sites/rid/Lists/BibliotecaDigital/RIDE/DE/DIJ/resolucion-3100-de-2019.pdf', true, 2),
  ('032326cf-409e-51fd-9750-968023ed00d3', '66cba8a9-8597-53d6-94a8-5fdacb81ba7d', 'licencia_practica_medica_radiaciones', 'Licencia de práctica médica (radiaciones ionizantes)', 'b. Si el prestador de servicios de salud hace uso de equipos generadores de radiaciones ionizantes en el servicio que pretende habilitar, debe anexar la copia impresa de la licencia de práctica médica vigente de los equipos que se encuentren en el servicio. Dicha licencia debe ser expedida por la secretaría de salud departamental o distrital, o la entidad que tenga a cargo dichas competencias. No es suficiente presentar el radicado del trámite de solicitud de la licencia para la inscripción o novedad en estos servicios de salud.', null, array['ips', 'profesional_independiente', 'transporte_especial', 'objeto_social_diferente']::text[], false, 'Solo si el servicio a habilitar usa equipos generadores de radiaciones ionizantes.', array['radiaciones_ionizantes']::text[], 'radicar', true, true, null, false, 'Resolución 3100 de 2019 (MinSalud)', 'Manual num. 9.1.3 lit. b', 'pág. 37', 'https://www.minsalud.gov.co/sites/rid/Lists/BibliotecaDigital/RIDE/DE/DIJ/resolucion-3100-de-2019.pdf', true, 3),
  ('7eb8d581-c946-58dd-a8bd-750b44845675', '66cba8a9-8597-53d6-94a8-5fdacb81ba7d', 'telemedicina_contrato_prestador_referencia', 'Telemedicina (remisor): contrato/convenio con prestador de referencia', 'Prestador remisor • Copia impresa del contrato o convenio con el prestador de referencia inscrito en el REPS, con una relación de los servicios de salud que el prestador de referencia le garantizará al prestador remisor. Cuando el prestador de referencia sea del mismo prestador deberá presentar documento con la relación de los servicios de salud que garantizará al prestador remisor.', null, array['ips', 'profesional_independiente', 'transporte_especial', 'objeto_social_diferente']::text[], false, 'Solo si habilita servicios en modalidad telemedicina como prestador remisor.', array['telemedicina_remisor']::text[], 'radicar', false, true, null, false, 'Resolución 3100 de 2019 (MinSalud)', 'Manual num. 9.1.3 lit. c (prestador remisor)', 'pág. 37', 'https://www.minsalud.gov.co/sites/rid/Lists/BibliotecaDigital/RIDE/DE/DIJ/resolucion-3100-de-2019.pdf', true, 4),
  ('a47ee1bb-d01f-57bb-960f-913bb67b63af', '66cba8a9-8597-53d6-94a8-5fdacb81ba7d', 'telemedicina_certificacion_conexion_internet', 'Telemedicina: certificación de conexión a internet', '• Copia impresa de la certificación de conexión a internet, que soporte el método de comunicación sincrónico o asincrónico, según sea el caso.', null, array['ips', 'profesional_independiente', 'transporte_especial', 'objeto_social_diferente']::text[], false, 'Solo si habilita servicios en modalidad telemedicina (remisor o de referencia).', array['telemedicina']::text[], 'radicar', true, false, null, false, 'Resolución 3100 de 2019 (MinSalud)', 'Manual num. 9.1.3 lit. c (remisor y referencia)', 'págs. 37-38', 'https://www.minsalud.gov.co/sites/rid/Lists/BibliotecaDigital/RIDE/DE/DIJ/resolucion-3100-de-2019.pdf', true, 5),
  ('c531b374-37ef-5e90-9f5f-3176499920c0', '66cba8a9-8597-53d6-94a8-5fdacb81ba7d', 'telemedicina_certificado_ingeniero_sistemas', 'Telemedicina: documento firmado por ingeniero de sistemas', '• Documento firmado por un ingeniero de sistemas con tarjeta profesional vigente, que certifica el cumplimiento de las responsabilidades determinadas para el uso de plataformas tecnológicas en telemedicina.', null, array['ips', 'profesional_independiente', 'transporte_especial', 'objeto_social_diferente']::text[], false, 'Solo si habilita servicios en modalidad telemedicina (remisor o de referencia).', array['telemedicina']::text[], 'radicar', false, false, null, false, 'Resolución 3100 de 2019 (MinSalud)', 'Manual num. 9.1.3 lit. c (remisor y referencia)', 'págs. 37-38', 'https://www.minsalud.gov.co/sites/rid/Lists/BibliotecaDigital/RIDE/DE/DIJ/resolucion-3100-de-2019.pdf', true, 6),
  ('2e320df4-1702-5513-af61-d96f162c9a1f', '66cba8a9-8597-53d6-94a8-5fdacb81ba7d', 'documento_identificacion_persona_natural', 'Documento de identificación (persona natural)', 'a. Copia impresa del documento de identificación.', null, array['profesional_independiente', 'transporte_especial']::text[], true, 'Profesional independiente (9.1.3.1 lit. a); transporte especial de pacientes cuando es persona natural (9.1.3.4 "Para persona natural" lit. a).', array['tep_solo_persona_natural']::text[], 'radicar', false, false, null, false, 'Resolución 3100 de 2019 (MinSalud)', 'Manual num. 9.1.3.1 lit. a; 9.1.3.4 (persona natural) lit. a', 'págs. 38 y 40', 'https://www.minsalud.gov.co/sites/rid/Lists/BibliotecaDigital/RIDE/DE/DIJ/resolucion-3100-de-2019.pdf', true, 7),
  ('3243a5a4-a8c7-5519-a91d-85fe73988408', '66cba8a9-8597-53d6-94a8-5fdacb81ba7d', 'certificado_existencia_representacion_legal', 'Certificado de existencia y representación legal (≤ 30 días)', 'IPS (9.1.3.3 a) y TEP persona jurídica (9.1.3.4 a): "Certificado de existencia y representación legal de la persona jurídica de acuerdo con su naturaleza jurídica, expedida por la autoridad competente, con vigencia no superior a 30 días a la fecha de solicitud de inscripción." OSD (9.1.3.2 a): "Copia impresa del certificado de existencia y representación legal vigente, no superior a 30 días a la fecha de radicación del formulario de inscripción."', null, array['ips', 'transporte_especial', 'objeto_social_diferente']::text[], true, 'TEP solo cuando es persona jurídica. Para IPS sin personería jurídica propiedad de EPS, caja de compensación, prepagada u otra entidad, se acredita con el certificado o acto de creación de la entidad a la cual pertenece (Manual 8.1.1.3, pág. 32).', array['tep_solo_persona_juridica']::text[], 'radicar', false, true, 'max_30_dias_radicacion', false, 'Resolución 3100 de 2019 (MinSalud)', 'Manual num. 9.1.3.2 lit. a; 9.1.3.3 lit. a; 9.1.3.4 lit. a; 8.1.1', 'págs. 31-32, 38-39', 'https://www.minsalud.gov.co/sites/rid/Lists/BibliotecaDigital/RIDE/DE/DIJ/resolucion-3100-de-2019.pdf', true, 8),
  ('6fcec158-0677-55f1-81a6-bf68bef9e3a7', '66cba8a9-8597-53d6-94a8-5fdacb81ba7d', 'certificado_matricula_sedes_sucursales', 'Certificado de matrícula de sedes/sucursales/agencias en otros departamentos', 'Entidades privadas con ánimo de lucro: "• Certificado de existencia y representación legal vigente de la persona jurídica expedido por la Cámara de Comercio. En dicho certificado se deberá especificar la ubicación de las sedes. • Cuando tenga sedes o sucursales o agencias en otros departamentos o distritos, adicional al certificado anterior, debe anexarse el certificado de matrícula de las sedes o sucursales o agencias donde se especifique la razón social principal, que debe ser igual a la indicada en el certificado de existencia y representación legal vigente." Art. 4 par. 2 (texto vigente): "Las entidades privadas con o sin ánimo de lucro, deberán aportar para la inscripción y trámite de novedades, cuando aplique, la ubicación de las sedes en uno o varios certificados expedidos por la autoridad competente, siempre y cuando se trate del mismo número de NIT."', null, array['ips', 'objeto_social_diferente', 'transporte_especial']::text[], false, 'Entidades privadas con sedes, sucursales o agencias en otros departamentos o distritos.', array['sedes_otros_departamentos']::text[], 'radicar', false, true, null, false, 'Resolución 3100 de 2019 (MinSalud)', 'Manual num. 8.1.1.1; Art. 4 par. 2 (Res. 465/2025 art. 1)', 'pág. 32; Res. 465 hoja 2', 'https://www.minsalud.gov.co/sites/rid/Lists/BibliotecaDigital/RIDE/DE/DIJ/resolucion-3100-de-2019.pdf', true, 9),
  ('9db80fd4-d0b6-52c7-ade8-af57ebac3d30', '66cba8a9-8597-53d6-94a8-5fdacb81ba7d', 'acto_personeria_juridica_esal', 'Acto de reconocimiento de personería jurídica (ESAL)', '8.1.1.2 Entidades privadas sin ánimo de lucro • Acto administrativo mediante el cual se les reconoce personería jurídica y representación legal expedida por la autoridad competente. En dicho documento se deberá especificar la ubicación de la o las sedes. • Certificado de existencia y representación legal vigente de la persona jurídica expedido por la Cámara de Comercio, cuando aplique. [...] • Para las sedes o sucursales, adicional al certificado anterior, deberá presentar el certificado del establecimiento de comercio correspondiente, cuando aplique.', null, array['ips', 'objeto_social_diferente', 'transporte_especial']::text[], false, 'Solo entidades privadas sin ánimo de lucro (fundación, asociación, corporación, economía solidaria, etc.).', array['esal']::text[], 'radicar', false, false, null, false, 'Resolución 3100 de 2019 (MinSalud)', 'Manual num. 8.1.1.2', 'pág. 32', 'https://www.minsalud.gov.co/sites/rid/Lists/BibliotecaDigital/RIDE/DE/DIJ/resolucion-3100-de-2019.pdf', true, 10),
  ('d1a463a1-c06e-5cf3-b351-87907b7d9601', '66cba8a9-8597-53d6-94a8-5fdacb81ba7d', 'acto_creacion_entidad_publica', 'Acto administrativo de creación (entidad pública)', '8.1.1.3 Entidades de derecho público • Las entidades de derecho público deben anexar el acto administrativo por el cual se les dio vida jurídica.', null, array['ips', 'objeto_social_diferente', 'transporte_especial']::text[], false, 'Solo entidades de derecho público (ESE y otras IPS públicas).', array['entidad_publica']::text[], 'radicar', false, false, null, false, 'Resolución 3100 de 2019 (MinSalud)', 'Manual num. 8.1.1.3', 'pág. 32', 'https://www.minsalud.gov.co/sites/rid/Lists/BibliotecaDigital/RIDE/DE/DIJ/resolucion-3100-de-2019.pdf', true, 11),
  ('2a693cc6-e25b-57c6-a28d-11742808d7f9', '66cba8a9-8597-53d6-94a8-5fdacb81ba7d', 'documento_domicilio_organismo_cooperacion', 'Documento de domicilio en Colombia (organismos de cooperación / ONG)', 'Art. 4 par. 1: "Cuando los organismos de cooperación internacional y los organismos no gubernamentales se inscriban en el Registro Especial de Prestadores de Servicios de Salud- REPS, como Entidades con Objeto Social Diferente o como Instituciones Prestadoras de Servicios de Salud - IPS, para registrar la o las sedes sólo deberán aportar el documento donde se especifique la ubicación del domicilio en el territorio nacional, expedido por la autoridad competente. Dicho domicilio para efectos de la presente norma se entenderá como sede."', null, array['ips', 'objeto_social_diferente']::text[], false, 'Solo organismos de cooperación internacional y ONG.', array['cooperacion_internacional']::text[], 'radicar', false, false, null, false, 'Resolución 465 de 2025 (MinSalud), modifica Res. 3100/2019', 'Art. 1 (modifica Art. 4 de la Res. 3100), par. 1', 'hoja 2', 'https://www.minsalud.gov.co/sites/rid/Lists/BibliotecaDigital/RIDE/DE/DIJ/resolucion-0465-de-2025.pdf', true, 12),
  ('b73362d6-40c0-544b-bb34-98658b54976f', '66cba8a9-8597-53d6-94a8-5fdacb81ba7d', 'documento_identidad_representante_legal', 'Documento de identidad del representante legal (o suplente)', 'Copia impresa del documento de identificación del representante legal o del suplente cuando aplique.', null, array['ips', 'objeto_social_diferente', 'transporte_especial']::text[], true, 'TEP solo cuando es persona jurídica.', array['tep_solo_persona_juridica']::text[], 'radicar', false, false, null, false, 'Resolución 3100 de 2019 (MinSalud)', 'Manual num. 9.1.3.2 lit. b; 9.1.3.3 lit. b; 9.1.3.4 lit. b', 'págs. 38-39', 'https://www.minsalud.gov.co/sites/rid/Lists/BibliotecaDigital/RIDE/DE/DIJ/resolucion-3100-de-2019.pdf', true, 13),
  ('82c29771-f13a-5a57-951f-fa49ebda6aed', '66cba8a9-8597-53d6-94a8-5fdacb81ba7d', 'nit', 'Copia del NIT', 'e. Copia impresa del NIT.', null, array['ips', 'transporte_especial']::text[], true, 'TEP solo cuando es persona jurídica.', array['tep_solo_persona_juridica']::text[], 'radicar', false, false, null, false, 'Resolución 3100 de 2019 (MinSalud)', 'Manual num. 9.1.3.3 lit. e; 9.1.3.4 lit. e', 'págs. 39', 'https://www.minsalud.gov.co/sites/rid/Lists/BibliotecaDigital/RIDE/DE/DIJ/resolucion-3100-de-2019.pdf', true, 14),
  ('5f8a1c3c-1d79-5f28-8d2a-2d2458faa7fd', '66cba8a9-8597-53d6-94a8-5fdacb81ba7d', 'rut', 'Copia del RUT', 'f. Copia impresa del RUT. (TEP persona natural, lit. b: "Copia impresa del RUT.")', null, array['ips', 'transporte_especial']::text[], true, 'IPS y TEP (persona jurídica y natural). NO aparece en la lista de soportes del profesional independiente (9.1.3.1) ni de la entidad con objeto social diferente (9.1.3.2). Para "toda nueva IPS" también figura como documento del sistema contable (8.1.2).', '{}'::text[], 'radicar', false, false, null, false, 'Resolución 3100 de 2019 (MinSalud)', 'Manual num. 9.1.3.3 lit. f; 9.1.3.4 lit. f y (persona natural) lit. b; 8.1.2', 'págs. 33, 39-40', 'https://www.minsalud.gov.co/sites/rid/Lists/BibliotecaDigital/RIDE/DE/DIJ/resolucion-3100-de-2019.pdf', true, 15),
  ('c03d2831-7fe3-535e-9f24-8e16ee429cfe', '66cba8a9-8597-53d6-94a8-5fdacb81ba7d', 'titulos_educacion_superior', 'Títulos de pregrado/posgrado (o convalidación MEN)', 'b. Copia impresa del título, o los títulos, de educación superior de pregrado y posgrado, según aplique, obtenidos de una Institución de Educación Superior. En el caso de títulos obtenidos en el extranjero copia impresa de la resolución de convalidación expedida por el Ministerio de Educación Nacional.', null, array['profesional_independiente']::text[], true, 'Convalidación solo si el título fue obtenido en el extranjero.', '{}'::text[], 'radicar', false, false, null, false, 'Resolución 3100 de 2019 (MinSalud)', 'Manual num. 9.1.3.1 lit. b', 'pág. 38', 'https://www.minsalud.gov.co/sites/rid/Lists/BibliotecaDigital/RIDE/DE/DIJ/resolucion-3100-de-2019.pdf', true, 16),
  ('4159bc99-28dc-5ffa-9874-f94192410ce5', '66cba8a9-8597-53d6-94a8-5fdacb81ba7d', 'tarjeta_profesional_o_rethus', 'Tarjeta profesional / autorización de ejercicio / ReTHUS', 'c. Copia impresa de la tarjeta profesional o de la resolución de autorización del ejercicio profesional expedida por la autoridad competente o inscripción en el Registro Único de Talento Humano en Salud - ReTHUS.', null, array['profesional_independiente']::text[], true, null, '{}'::text[], 'radicar', false, false, null, false, 'Resolución 3100 de 2019 (MinSalud)', 'Manual num. 9.1.3.1 lit. c', 'pág. 38', 'https://www.minsalud.gov.co/sites/rid/Lists/BibliotecaDigital/RIDE/DE/DIJ/resolucion-3100-de-2019.pdf', true, 17),
  ('c5df44e1-ad68-5cc9-ae33-5daccf592e39', '66cba8a9-8597-53d6-94a8-5fdacb81ba7d', 'certificado_instalaciones_electricas', 'Certificado de conformidad de instalaciones eléctricas (RETIE)', 'Copia impresa del certificado de conformidad de las instalaciones eléctricas. • Para prestadores que funcionen en edificaciones construidas con anterioridad a mayo del 2005, se solicitará una certificación expedida por un profesional competente en la cual certifique que las instalaciones eléctricas de la edificación donde se prestan los servicios de salud no representan alto riesgo para la salud y la vida de las personas y animales, o atenten contra el medio ambiente. Adicionalmente el prestador deberá presentar un plan de ajustes de las instalaciones eléctricas. • Para prestadores que funcionen en edificaciones construidas con posterioridad a mayo del 2005, o edificaciones adaptadas como instituciones de salud, se solicitará una certificación expedida por un organismo de inspección acreditado por la ONAC.', null, array['profesional_independiente', 'objeto_social_diferente', 'ips']::text[], true, 'Edificación anterior a mayo de 2005: certificación de profesional competente + plan de ajustes. Posterior a mayo de 2005 o adaptada: certificación de organismo de inspección acreditado por ONAC. No aparece en la lista de TEP (9.1.3.4).', '{}'::text[], 'radicar', true, false, null, false, 'Resolución 3100 de 2019 (MinSalud)', 'Manual num. 9.1.3.1 lit. d; 9.1.3.2 lit. e; 9.1.3.3 lit. l', 'págs. 38-39', 'https://www.minsalud.gov.co/sites/rid/Lists/BibliotecaDigital/RIDE/DE/DIJ/resolucion-3100-de-2019.pdf', true, 18),
  ('e8e1f1b5-68ab-5772-b1d8-b1e3eb343da6', '66cba8a9-8597-53d6-94a8-5fdacb81ba7d', 'plan_ajustes_instalaciones_electricas', 'Plan de ajustes de instalaciones eléctricas', 'Adicionalmente el prestador deberá presentar un plan de ajustes de las instalaciones eléctricas.', null, array['profesional_independiente', 'objeto_social_diferente', 'ips']::text[], false, 'Solo edificaciones construidas antes de mayo de 2005.', array['edificacion_pre_2005_05']::text[], 'radicar', true, false, null, false, 'Resolución 3100 de 2019 (MinSalud)', 'Manual num. 9.1.3.1 lit. d; 9.1.3.2 lit. e; 9.1.3.3 lit. l', 'págs. 38-39', 'https://www.minsalud.gov.co/sites/rid/Lists/BibliotecaDigital/RIDE/DE/DIJ/resolucion-3100-de-2019.pdf', true, 19),
  ('dab72b96-ebc1-56ec-9955-72159c694cf1', '66cba8a9-8597-53d6-94a8-5fdacb81ba7d', 'licencia_construccion', 'Licencia de construcción (o reconocimiento de la edificación)', 'Manual (IPS lit. g y OSD lit. c): "Copia impresa de la licencia de construcción. • Es exigible a edificaciones [...] construidas, ampliadas o remodeladas con posterioridad al 2 de diciembre de 1996." Art. 7 par. 2 (texto vigente, Res. 465/2025): "Si dichas edificaciones fueron construidas con posterioridad a 2010, el prestador sólo deberá aportar la licencia de construcción en donde se evidencia la destinación para la prestación de servicios de salud. Las instituciones prestadoras de servicios de salud que funcionen en edificaciones construidas antes del 2 de diciembre de 1996, al radicar el formulario de inscripción, deben aportar copia de la licencia de construcción o en su defecto el documento de reconocimiento de la edificación expedido por autoridad competente, que autorice la destinación de la edificación para la prestación de servicios de salud. Las entidades con objeto social diferente deberán aportar la licencia de construcción."', null, array['ips', 'objeto_social_diferente']::text[], true, 'IPS: desde Res. 544/2023 (y 465/2025) también las edificaciones anteriores al 2-dic-1996 deben aportar licencia o documento de reconocimiento. OSD: licencia de construcción. No exigido en la lista del profesional independiente ni de TEP.', '{}'::text[], 'radicar', true, false, null, false, 'Res. 3100/2019 Manual + Res. 465/2025 (Art. 7 par. 2)', 'Manual 9.1.3.2 lit. c; 9.1.3.3 lit. g; Art. 7 par. 2', 'Res. 3100 págs. 38-39; Res. 465 hoja 4', 'https://www.minsalud.gov.co/sites/rid/Lists/BibliotecaDigital/RIDE/DE/DIJ/resolucion-0465-de-2025.pdf', true, 20),
  ('bb873781-eec4-5d41-bb7f-c8413216ba4e', '66cba8a9-8597-53d6-94a8-5fdacb81ba7d', 'permiso_propiedad_horizontal', 'Permiso de la propiedad horizontal (edificio de uso mixto)', '• Para prestadores ubicados en edificaciones de uso mixto construidas, ampliadas o remodeladas con posterioridad al 2 de diciembre de 1996, se solicitará el permiso otorgado por la propiedad horizontal para la adecuación en la edificación de servicios de salud, y la licencia de construcción de la edificación.', null, array['ips', 'objeto_social_diferente']::text[], false, 'Edificación de uso mixto construida/ampliada/remodelada después del 2-dic-1996.', array['edificacion_post_1996_mixta']::text[], 'radicar', true, false, null, false, 'Resolución 3100 de 2019 (MinSalud)', 'Manual num. 9.1.3.2 lit. c; 9.1.3.3 lit. g', 'págs. 38-39', 'https://www.minsalud.gov.co/sites/rid/Lists/BibliotecaDigital/RIDE/DE/DIJ/resolucion-3100-de-2019.pdf', true, 21),
  ('16e83c36-9c5e-54d6-b2a2-a0b3f08fe7fc', '66cba8a9-8597-53d6-94a8-5fdacb81ba7d', 'certificado_seguridad_edificacion', 'Certificado de seguridad de la edificación', 'h. Copia impresa del certificado de seguridad de la edificación.', null, array['ips']::text[], true, 'La norma no define qué autoridad lo expide ni su contenido.', '{}'::text[], 'radicar', true, false, null, false, 'Resolución 3100 de 2019 (MinSalud)', 'Manual num. 9.1.3.3 lit. h', 'pág. 39', 'https://www.minsalud.gov.co/sites/rid/Lists/BibliotecaDigital/RIDE/DE/DIJ/resolucion-3100-de-2019.pdf', true, 22),
  ('c29a36d3-cdc8-5a5c-a2ed-280599db51b7', '66cba8a9-8597-53d6-94a8-5fdacb81ba7d', 'estudio_vulnerabilidad_estructural', 'Estudio de vulnerabilidad estructural (NSR-10)', 'i. Copia impresa del estudio de vulnerabilidad estructural. • Sólo será exigible a prestadores con servicios de urgencias, servicios de cirugía, o de unidad de cuidado intensivo neonatal, pediátrico, adulto, de acuerdo con lo establecido en la NSR 10 que funcionen en edificaciones construidas con anterioridad al 2010.', null, array['ips']::text[], false, 'IPS con urgencias, cirugía o UCI (neonatal, pediátrica, adulto) en edificación construida antes de 2010.', array['edificacion_pre_2010_con_urgencias_cirugia_uci']::text[], 'radicar', true, false, null, false, 'Resolución 3100 de 2019 (MinSalud)', 'Manual num. 9.1.3.3 lit. i', 'pág. 39', 'https://www.minsalud.gov.co/sites/rid/Lists/BibliotecaDigital/RIDE/DE/DIJ/resolucion-3100-de-2019.pdf', true, 23),
  ('1c07df79-4168-5a6e-8b26-ef7196a9e723', '66cba8a9-8597-53d6-94a8-5fdacb81ba7d', 'plan_reforzamiento_estructural', 'Plan de cumplimiento para reforzamiento estructural', 'Art. 7 par. 2: "Cuando una institución prestadora de servicios de salud con servicios de urgencias, de cirugía, o de cuidado intensivo neonatal, pediátrico o adulto, funcionen en edificaciones construidas con anterioridad al 2010, radique el formulario de inscripción, deberá aportar la evidencia de haber realizado el estudio de vulnerabilidad estructural y adicionalmente un plan de cumplimiento para el reforzamiento estructural de la edificación en el marco de la normativa vigente."', null, array['ips']::text[], false, 'Mismo supuesto del estudio de vulnerabilidad (urgencias/cirugía/UCI en edificación anterior a 2010). Requisito nuevo introducido por Res. 544/2023 y mantenido por Res. 465/2025.', array['edificacion_pre_2010_con_urgencias_cirugia_uci']::text[], 'radicar', true, false, null, false, 'Resolución 465 de 2025 (MinSalud), modifica Res. 3100/2019', 'Art. 3 (modifica Art. 7 de la Res. 3100), par. 2', 'hoja 4', 'https://www.minsalud.gov.co/sites/rid/Lists/BibliotecaDigital/RIDE/DE/DIJ/resolucion-0465-de-2025.pdf', true, 24),
  ('7007a522-f707-59cb-afe8-41feadb90a77', '66cba8a9-8597-53d6-94a8-5fdacb81ba7d', 'plan_hospitalario_emergencias', 'Plan hospitalario para emergencias', 'j. Copia impresa del plan hospitalario para emergencias.', null, array['ips']::text[], true, null, '{}'::text[], 'radicar', false, false, null, false, 'Resolución 3100 de 2019 (MinSalud)', 'Manual num. 9.1.3.3 lit. j; verificado también en visita previa 9.3.4.1', 'págs. 39, 43', 'https://www.minsalud.gov.co/sites/rid/Lists/BibliotecaDigital/RIDE/DE/DIJ/resolucion-3100-de-2019.pdf', true, 25),
  ('b194dcc2-e72f-5abb-9d3c-2e15959979c7', '66cba8a9-8597-53d6-94a8-5fdacb81ba7d', 'plan_mantenimiento_planta_fisica', 'Plan de mantenimiento de la planta física (incluye equipamiento fijo)', 'IPS (lit. k): "Copia impresa del plan de mantenimiento de la planta física: • Todos los planes de mantenimiento deben incluir el equipamiento fijo." OSD (lit. d): "Copia impresa del plan de mantenimiento de la planta física. • Podrá ser el correspondiente al de la edificación donde se preste el servicio. • Todos los planes de mantenimiento deben incluir al equipamiento fijo."', null, array['ips', 'objeto_social_diferente']::text[], true, 'OSD puede presentar el plan de la edificación donde presta el servicio.', '{}'::text[], 'radicar', false, false, null, false, 'Resolución 3100 de 2019 (MinSalud)', 'Manual num. 9.1.3.2 lit. d; 9.1.3.3 lit. k', 'págs. 38-39', 'https://www.minsalud.gov.co/sites/rid/Lists/BibliotecaDigital/RIDE/DE/DIJ/resolucion-3100-de-2019.pdf', true, 26),
  ('a2476629-2f35-5d56-9925-721453a29836', '66cba8a9-8597-53d6-94a8-5fdacb81ba7d', 'certificacion_suficiencia_patrimonial', 'Certificación de suficiencia patrimonial y financiera', 'c. Certificación de suficiencia patrimonial y financiera, emitida por el revisor fiscal o contador según aplique.', null, array['ips', 'transporte_especial']::text[], true, 'TEP solo persona jurídica (la lista de TEP persona natural no la incluye). Indicadores en "condiciones_habilitacion.suficiencia_patrimonial_financiera".', array['tep_solo_persona_juridica']::text[], 'radicar', false, false, null, false, 'Resolución 3100 de 2019 (MinSalud)', 'Manual num. 9.1.3.3 lit. c; 9.1.3.4 lit. c; Art. 3.2 (texto Res. 544/2023)', 'pág. 39', 'https://www.minsalud.gov.co/sites/rid/Lists/BibliotecaDigital/RIDE/DE/DIJ/resolucion-3100-de-2019.pdf', true, 27),
  ('1e62054b-34ff-5cf2-b132-3f9408aca715', '66cba8a9-8597-53d6-94a8-5fdacb81ba7d', 'tarjeta_profesional_contador_revisor', 'Tarjeta profesional del contador y/o revisor fiscal', 'd. Copia impresa de la tarjeta profesional del contador y/o revisor fiscal, según aplique.', null, array['ips', 'transporte_especial']::text[], true, 'TEP solo persona jurídica.', array['tep_solo_persona_juridica']::text[], 'radicar', false, false, null, false, 'Resolución 3100 de 2019 (MinSalud)', 'Manual num. 9.1.3.3 lit. d; 9.1.3.4 lit. d', 'pág. 39', 'https://www.minsalud.gov.co/sites/rid/Lists/BibliotecaDigital/RIDE/DE/DIJ/resolucion-3100-de-2019.pdf', true, 28),
  ('cb31d2dd-c65c-58e3-8dec-4780be539146', '66cba8a9-8597-53d6-94a8-5fdacb81ba7d', 'estados_financieros', 'Estados financieros (constitución, intermedios o cierre)', '• Estados financieros de constitución o de periodos intermedios o de cierre de vigencia: certificados o dictaminados cuando aplique. Cuando se trate de la apertura de una nueva Institución Prestadora de Servicios de Salud sin personería jurídica y de propiedad de una entidad promotora de salud, entidad adaptada, caja de compensación familiar, empresa de medicina prepagada o de otra entidad, sea este o no su objeto social, presentará los estados financieros consolidados certificados o dictaminados, de la entidad que es propietaria, según corresponda.', null, array['ips']::text[], true, '"Toda nueva institución prestadora de servicios de salud debe contar con" (condición técnico-administrativa, sistema contable). OJO: no figura en la lista de soportes a radicar del 9.1.3.3; es evidencia que puede pedirse en verificación.', array['ips_nueva']::text[], 'evidencia_visita', false, false, null, false, 'Resolución 3100 de 2019 (MinSalud)', 'Manual num. 8.1.2 y 8.2', 'págs. 32-33', 'https://www.minsalud.gov.co/sites/rid/Lists/BibliotecaDigital/RIDE/DE/DIJ/resolucion-3100-de-2019.pdf', true, 29),
  ('409accb4-117a-5d6f-9f06-84d7b5320c16', '66cba8a9-8597-53d6-94a8-5fdacb81ba7d', 'certificado_cuenta_bancaria_ips', 'Certificado de cuenta bancaria a nombre de la IPS', '• Certificado de cuenta bancaria cuyo titular sea la IPS.', null, array['ips']::text[], true, 'Toda nueva IPS (8.1.2). No figura en la lista de soportes a radicar del 9.1.3.3.', array['ips_nueva']::text[], 'evidencia_visita', false, false, null, false, 'Resolución 3100 de 2019 (MinSalud)', 'Manual num. 8.1.2', 'pág. 33', 'https://www.minsalud.gov.co/sites/rid/Lists/BibliotecaDigital/RIDE/DE/DIJ/resolucion-3100-de-2019.pdf', true, 30),
  ('449747f2-f797-59b2-8b85-e725e22a967d', '66cba8a9-8597-53d6-94a8-5fdacb81ba7d', 'libros_oficiales', 'Libros oficiales registrados', '• Libros oficiales registrados ante el ente correspondiente, cuando aplique.', null, array['ips']::text[], false, 'Toda nueva IPS, "cuando aplique" (8.1.2). No figura en la lista de soportes a radicar del 9.1.3.3.', array['ips_nueva']::text[], 'evidencia_visita', false, false, null, false, 'Resolución 3100 de 2019 (MinSalud)', 'Manual num. 8.1.2', 'pág. 33', 'https://www.minsalud.gov.co/sites/rid/Lists/BibliotecaDigital/RIDE/DE/DIJ/resolucion-3100-de-2019.pdf', true, 31),
  ('18b117b3-6819-5f88-a89e-d0550f129cc1', '66cba8a9-8597-53d6-94a8-5fdacb81ba7d', 'reporte_obligaciones_mercantiles_vencidas', 'Reporte certificado de obligaciones mercantiles vencidas > 360 días', 'Para la obtención del valor del numerador, se solicitará a la entidad un reporte, certificado por el revisor fiscal y/o contador de las cuentas por pagar a los proveedores y demás obligaciones mercantiles que superen un período más de 360 días calendario contados a partir de la fecha de surgimiento de la obligación, con corte a la fecha de la verificación.', null, array['ips', 'transporte_especial']::text[], false, 'Se solicita para calcular el indicador 8.2.2 (con corte a la fecha de la verificación).', array['tep_solo_persona_juridica']::text[], 'evidencia_visita', false, false, null, false, 'Resolución 3100 de 2019 (MinSalud)', 'Manual num. 8.2.2', 'pág. 34', 'https://www.minsalud.gov.co/sites/rid/Lists/BibliotecaDigital/RIDE/DE/DIJ/resolucion-3100-de-2019.pdf', true, 32),
  ('4569ab15-bc9a-5cd5-afd2-77951c4dffc3', '66cba8a9-8597-53d6-94a8-5fdacb81ba7d', 'reporte_obligaciones_laborales_vencidas', 'Reporte certificado de obligaciones laborales vencidas > 360 días', 'Para la obtención del valor del numerador, se solicitará a la entidad un reporte, certificado por el revisor fiscal o contador de las moras de pago de nómina y demás obligaciones laborales que superen un período más de 360 días calendario contados a partir de la fecha de surgimiento de la obligación, con corte a la fecha de la verificación.', null, array['ips', 'transporte_especial']::text[], false, 'Se solicita para calcular el indicador 8.2.3 (con corte a la fecha de la verificación).', array['tep_solo_persona_juridica']::text[], 'evidencia_visita', false, false, null, false, 'Resolución 3100 de 2019 (MinSalud)', 'Manual num. 8.2.3', 'pág. 34', 'https://www.minsalud.gov.co/sites/rid/Lists/BibliotecaDigital/RIDE/DE/DIJ/resolucion-3100-de-2019.pdf', true, 33),
  ('f237b375-62a5-546f-b660-a1af3369b04e', '66cba8a9-8597-53d6-94a8-5fdacb81ba7d', 'tarjeta_propiedad_vehiculos', 'Tarjeta de propiedad de los vehículos (+ autorización del propietario)', 'Copia impresa de la tarjeta de propiedad de los vehículos o documento equivalente, si estos se encuentran a nombre de una persona diferente del representante legal adicionalmente anexar documento de autorización del propietario donde indique que los vehículos harán parte de la capacidad instalada del servicio a habilitar. [OSD que habilite TAB/TAM, Art. 20.1 vigente: "Copia impresa de la tarjeta de propiedad de los vehículos. Si estos se encuentran a nombre de una persona diferente al prestador, también debe anexar el documento de autorización del propietario donde indique que los vehículos harán parte de la capacidad instalada del servicio a habilitar."]', null, array['transporte_especial', 'ips', 'objeto_social_diferente']::text[], false, 'TEP: siempre (9.1.3.4). IPS: si declara transporte asistencial (ambulancias) o atención prehospitalaria (9.1.3.3 m). OSD: si habilita Transporte Asistencial Básico o Medicalizado (Art. 20, Res. 465/2025).', array['vehiculos']::text[], 'radicar', false, false, null, false, 'Res. 3100/2019 Manual + Res. 465/2025 Art. 5 (Art. 20)', 'Manual 9.1.3.3 lit. m; 9.1.3.4 lit. g y (PN) lit. c; Art. 20.1', 'Res. 3100 págs. 39-40; Res. 465 hoja 7', 'https://www.minsalud.gov.co/sites/rid/Lists/BibliotecaDigital/RIDE/DE/DIJ/resolucion-3100-de-2019.pdf', true, 34),
  ('d3912d1f-b7c0-5eb9-8808-5634780534df', '66cba8a9-8597-53d6-94a8-5fdacb81ba7d', 'revision_tecnico_mecanica', 'Certificado de revisión técnico-mecánica', 'Copia impresa del certificado de revisión técnico - mecánica o documento equivalente, cuando aplique de conformidad con las normas que regulan la materia.', null, array['transporte_especial', 'ips', 'objeto_social_diferente']::text[], false, 'Mismos supuestos que la tarjeta de propiedad; "cuando aplique".', array['vehiculos']::text[], 'radicar', false, true, null, false, 'Res. 3100/2019 Manual + Res. 465/2025 Art. 5 (Art. 20)', 'Manual 9.1.3.3 lit. m; 9.1.3.4 lit. h y (PN) lit. d; Art. 20.2', 'Res. 3100 págs. 39-40; Res. 465 hoja 7', 'https://www.minsalud.gov.co/sites/rid/Lists/BibliotecaDigital/RIDE/DE/DIJ/resolucion-3100-de-2019.pdf', true, 35),
  ('7d537da6-2fc6-5e27-b6f6-8cbc962273ed', '66cba8a9-8597-53d6-94a8-5fdacb81ba7d', 'poliza_responsabilidad_civil', 'Póliza de responsabilidad civil', 'NO ENCONTRADO en fuente oficial: la Res. 3100/2019 (Arts. 7-8 y Manual num. 9.1.3) ni sus modificatorias 544/2023 y 465/2025 la exigen como soporte de inscripción.', null, '{}'::text[], false, 'No incluir como requisito de inscripción sin otra norma que lo respalde.', '{}'::text[], 'radicar', false, false, null, false, 'Resolución 3100 de 2019 (MinSalud)', 'Búsqueda negativa en Arts. 7-8 y Manual 8-9', 'n/a', 'https://www.minsalud.gov.co/sites/rid/Lists/BibliotecaDigital/RIDE/DE/DIJ/resolucion-3100-de-2019.pdf', false, 36),
  ('ce3f4f8c-7b60-560c-ab18-1c6353fe6d30', '66cba8a9-8597-53d6-94a8-5fdacb81ba7d', 'rut_profesional_independiente', 'RUT del profesional independiente', 'NO ENCONTRADO como soporte de inscripción del profesional independiente (9.1.3.1 solo lista: documento de identificación, títulos, tarjeta profesional/ReTHUS y certificado de instalaciones eléctricas).', null, '{}'::text[], false, 'Algunas secretarías podrían pedirlo, pero el Art. 18 prohíbe exigir requisitos distintos a los de la norma.', '{}'::text[], 'radicar', false, false, null, false, 'Resolución 3100 de 2019 (MinSalud)', 'Manual num. 9.1.3.1; Art. 18', 'págs. 10, 38', 'https://www.minsalud.gov.co/sites/rid/Lists/BibliotecaDigital/RIDE/DE/DIJ/resolucion-3100-de-2019.pdf', false, 37)
insert into hab_obligaciones_catalogo (id, norma_id, codigo, nombre, descripcion_corta, entidad, plataforma_nombre, plataforma_url, norma_nombre, norma_numero, norma_articulo, norma_url, url_instructivo, enlace_verificado_el, url_responde, periodicidad, aplica_a_tipos, aplica_a_grupos, condiciones, activacion_default, requiere_confirmacion_asesor, dias_aviso_default, verificado, notas) values
  ('95507717-6b13-5e5c-94a3-2b00b3f44429', '66cba8a9-8597-53d6-94a8-5fdacb81ba7d', 'FT001', 'FT001 - Catálogo de Información Financiera (con fines de supervisión)', 'Saldos contables de la IPS según el catálogo de conceptos financieros de la Supersalud (equivale a un balance y estado de resultados codificado). Se genera en XML y se firma digitalmente por representante legal, contador y revisor fiscal (si aplica). Las IPS C2, D1, D2 y D3 reportan el código del concepto a 6 dígitos.', 'supersalud', 'nRVCC - Sistema de Recepción, Validación y Cargue de la Supersalud (https://nrvcc.supersalud.gov.co/), archivo XML firmado digitalmente', 'https://nrvcc.supersalud.gov.co/', 'Circular Externa Supersalud 2024151000000007-5 (modifica la Circular Única 047 de 2007; archivo creado por la CE 016 de 2016)', '2024151000000007-5', 'Instrucción OCTAVA, numeral 1 ''Anexo Técnico Archivo Tipo FT001''', 'https://docs.supersalud.gov.co/PortalWeb/Juridica/CircularesExterna/Circular%20externa%20n%C3%BAmero%202024151000000007-5%20de%202024.pdf', 'https://docs.supersalud.gov.co/PortalWeb/metodologias/OtrosDocumentosMetodologias/INSTRUCTIVO%20FT001.pdf', '2026-10-06', true, 'semestral', array['ips', 'transporte_especial']::text[], null, array['privada_o_mixta']::text[], 'auto', false, array[30, 15, 7, 1, 0]::int[], true, 'Instructivo FT001 versión 10 publicado 04/08/2026 confirma la misma tabla de periodicidad. Catálogos (Anexo 1) actualizados 13/04/2026 en el módulo de circulares. 2027-02-20 cae sábado y 2027-07-20 es festivo (Día de la Independencia): la norma fija fecha calendario; NO se verificó si Supersalud corre el plazo al día hábil siguiente -> alertar con anticipación y tratar la fecha literal como límite.
