insert into hab_novedades_catalogo (id, norma_id, codigo, categoria, nombre, definicion_literal, fuente_norma, fuente_articulo, fuente_pagina, fuente_url, efecto, orden) values
  ('81291016-cfea-5cfb-b7e6-23fb7822e785', '66cba8a9-8597-53d6-94a8-5fdacb81ba7d', 'cierre_prestador', 'prestador', 'Cierre del prestador de servicios de salud', 'Retiro del prestador de servicios de salud del REPS, momento a partir del cual no puede prestar servicios de salud.', 'Resolución 3100 de 2019 (MinSalud)', 'Art. 12.1; Manual 10.1', 'págs. 6, 46', 'https://www.minsalud.gov.co/sites/rid/Lists/BibliotecaDigital/RIDE/DE/DIJ/resolucion-3100-de-2019.pdf', null, 1),
  ('fdf09ce3-0a3a-56b4-ac60-41099a9d537b', '66cba8a9-8597-53d6-94a8-5fdacb81ba7d', 'disolucion_liquidacion', 'prestador', 'Disolución y liquidación de la entidad', 'Es el acto jurídico a través del cual el prestador de servicios de salud suspende el desarrollo de su actividad social y entra en el proceso para finiquitar su operación y proceder a la liquidación. En la gestión de la correspondiente novedad y su registro, el prestador de servicios de salud debe presentar el certificado expedido por la Cámara de Comercio o la autoridad competente, en el que conste la disolución y liquidación.', 'Resolución 3100 de 2019 (MinSalud)', 'Art. 12.1; Manual 10.1', 'págs. 6, 46', 'https://www.minsalud.gov.co/sites/rid/Lists/BibliotecaDigital/RIDE/DE/DIJ/resolucion-3100-de-2019.pdf', null, 2),
  ('205a01b6-8a7a-5fb7-8e68-af261a7ab238', '66cba8a9-8597-53d6-94a8-5fdacb81ba7d', 'cambio_domicilio_prestador', 'prestador', 'Cambio de domicilio', 'Registro en el REPS de la ubicación de un nuevo domicilio del prestador de servicios de salud.', 'Resolución 3100 de 2019 (MinSalud)', 'Art. 12.1; Manual 10.1', 'págs. 6, 46', 'https://www.minsalud.gov.co/sites/rid/Lists/BibliotecaDigital/RIDE/DE/DIJ/resolucion-3100-de-2019.pdf', null, 3),
  ('343e76c3-1870-5227-8097-82d7ecbf34f4', '66cba8a9-8597-53d6-94a8-5fdacb81ba7d', 'cambio_nomenclatura_prestador', 'prestador', 'Cambio de nomenclatura', 'Registro en el REPS de cambios en alguno de los campos que conforman la dirección del prestador de servicios de salud.', 'Resolución 3100 de 2019 (MinSalud)', 'Art. 12.1; Manual 10.1', 'págs. 6, 46', 'https://www.minsalud.gov.co/sites/rid/Lists/BibliotecaDigital/RIDE/DE/DIJ/resolucion-3100-de-2019.pdf', null, 4),
  ('8de9b288-8ed4-5ef9-9a81-157278c60062', '66cba8a9-8597-53d6-94a8-5fdacb81ba7d', 'cambio_representante_legal', 'prestador', 'Cambio de representante legal', 'Registro en el REPS del nombre del nuevo representante legal del prestador de servicios de salud.', 'Resolución 3100 de 2019 (MinSalud)', 'Art. 12.1; Manual 10.1', 'págs. 6, 46', 'https://www.minsalud.gov.co/sites/rid/Lists/BibliotecaDigital/RIDE/DE/DIJ/resolucion-3100-de-2019.pdf', null, 5),
  ('3de31cbe-c029-5f60-a105-abcaf82083ee', '66cba8a9-8597-53d6-94a8-5fdacb81ba7d', 'cambio_razon_social', 'prestador', 'Cambio de razón social o nombre que no implique cambio de NIT, ni de documento de identidad', 'Registro en el REPS del cambio del nombre del prestador de servicios de salud, teniendo en cuenta que el documento que lo soporta no involucra el cambio del NIT o del documento de identificación, según corresponda.', 'Resolución 3100 de 2019 (MinSalud)', 'Art. 12.1; Manual 10.1', 'págs. 6, 46', 'https://www.minsalud.gov.co/sites/rid/Lists/BibliotecaDigital/RIDE/DE/DIJ/resolucion-3100-de-2019.pdf', null, 6),
  ('300e7837-4366-5fb3-a982-e1b520a27428', '66cba8a9-8597-53d6-94a8-5fdacb81ba7d', 'cambio_contacto_prestador', 'prestador', 'Cambio de datos de contacto (teléfono y correo electrónico)', 'Registro en el REPS del nuevo teléfono y correo electrónico donde se puede contactar al prestador de servicios de salud.', 'Resolución 3100 de 2019 (MinSalud)', 'Art. 12.1; Manual 10.1', 'págs. 6, 46', 'https://www.minsalud.gov.co/sites/rid/Lists/BibliotecaDigital/RIDE/DE/DIJ/resolucion-3100-de-2019.pdf', null, 7),
  ('9102bb4b-a0e5-56af-a077-1eee7cccdf0b', '66cba8a9-8597-53d6-94a8-5fdacb81ba7d', 'apertura_sede', 'sede', 'Apertura de sede', 'Registro en el REPS de una nueva sede del prestador de servicios de salud, donde prestará servicios de salud.', 'Resolución 3100 de 2019 (MinSalud)', 'Art. 12.2; Manual 10.2', 'págs. 6, 46-47', 'https://www.minsalud.gov.co/sites/rid/Lists/BibliotecaDigital/RIDE/DE/DIJ/resolucion-3100-de-2019.pdf', null, 8),
  ('d98ca9ea-192b-5fcc-8e99-9ecbfd1096b3', '66cba8a9-8597-53d6-94a8-5fdacb81ba7d', 'cierre_sede', 'sede', 'Cierre de sede', 'Registro en el REPS del retiro de una sede del prestador de servicios de salud, en la cual no continuará prestando servicios de salud. Para el caso de cierre de sede cuando se tiene solamente una, se debe aplicar la novedad de cierre de prestador. Si el prestador de servicios de salud tiene más de una sede y requiere realizar cierre de la sede principal, debe realizar primero la novedad de cambio de sede principal y de manera posterior la novedad de cierre de sede.', 'Resolución 3100 de 2019 (MinSalud)', 'Art. 12.2; Manual 10.2', 'págs. 6, 46-47', 'https://www.minsalud.gov.co/sites/rid/Lists/BibliotecaDigital/RIDE/DE/DIJ/resolucion-3100-de-2019.pdf', null, 9),
  ('921af4df-ba3f-5a42-8226-20338b0f9d20', '66cba8a9-8597-53d6-94a8-5fdacb81ba7d', 'cambio_domicilio_sede', 'sede', 'Cambio de domicilio', 'Registro en el REPS de la nueva dirección de una sede del prestador de servicios de salud.', 'Resolución 3100 de 2019 (MinSalud)', 'Art. 12.2; Manual 10.2', 'págs. 6, 46-47', 'https://www.minsalud.gov.co/sites/rid/Lists/BibliotecaDigital/RIDE/DE/DIJ/resolucion-3100-de-2019.pdf', null, 10),
  ('e0891eec-f70c-579a-b282-a3d2ee4734d2', '66cba8a9-8597-53d6-94a8-5fdacb81ba7d', 'cambio_nomenclatura_sede', 'sede', 'Cambio de nomenclatura', 'Registro en el REPS de cambios en alguno de los campos que conforman la dirección de una sede del prestador de servicios de salud.', 'Resolución 3100 de 2019 (MinSalud)', 'Art. 12.2; Manual 10.2', 'págs. 6, 46-47', 'https://www.minsalud.gov.co/sites/rid/Lists/BibliotecaDigital/RIDE/DE/DIJ/resolucion-3100-de-2019.pdf', null, 11),
  ('53f603ae-812d-5056-918c-e8aaa9315a77', '66cba8a9-8597-53d6-94a8-5fdacb81ba7d', 'cambio_sede_principal', 'sede', 'Cambio de sede principal', 'Registro en el REPS del cambio de la sede identificada por el prestador de servicios de salud como principal.', 'Resolución 3100 de 2019 (MinSalud)', 'Art. 12.2; Manual 10.2', 'págs. 6, 46-47', 'https://www.minsalud.gov.co/sites/rid/Lists/BibliotecaDigital/RIDE/DE/DIJ/resolucion-3100-de-2019.pdf', null, 12),
  ('3f523d84-3929-542b-b2a8-cc107197ed2f', '66cba8a9-8597-53d6-94a8-5fdacb81ba7d', 'cambio_contacto_sede', 'sede', 'Cambio de datos de contacto (teléfono y correo electrónico)', 'Registro en el REPS del nuevo teléfono y correo electrónico de una sede.', 'Resolución 3100 de 2019 (MinSalud)', 'Art. 12.2; Manual 10.2', 'págs. 6, 46-47', 'https://www.minsalud.gov.co/sites/rid/Lists/BibliotecaDigital/RIDE/DE/DIJ/resolucion-3100-de-2019.pdf', null, 13),
  ('005362a8-31fd-5c94-84cf-9fb144ee06d8', '66cba8a9-8597-53d6-94a8-5fdacb81ba7d', 'cambio_director_sede', 'sede', 'Cambio de director, gerente, administrador o responsable', 'Registro en el REPS del cambio de nombre del director, gerente, administrador o responsable de una sede.', 'Resolución 3100 de 2019 (MinSalud)', 'Art. 12.2; Manual 10.2', 'págs. 6, 46-47', 'https://www.minsalud.gov.co/sites/rid/Lists/BibliotecaDigital/RIDE/DE/DIJ/resolucion-3100-de-2019.pdf', null, 14),
  ('e88edd34-b33a-50d2-affd-16124a761296', '66cba8a9-8597-53d6-94a8-5fdacb81ba7d', 'cambio_nombre_sede', 'sede', 'Cambio de nombre de la sede, que no implique cambio de razón social', 'Registro en el REPS del cambio del nombre de la sede, teniendo en cuenta que el documento que lo soporta no involucra el cambio de razón social, NIT o del documento de identificación, según corresponda.', 'Resolución 3100 de 2019 (MinSalud)', 'Art. 12.2; Manual 10.2', 'págs. 6, 46-47', 'https://www.minsalud.gov.co/sites/rid/Lists/BibliotecaDigital/RIDE/DE/DIJ/resolucion-3100-de-2019.pdf', null, 15),
  ('dc12c52d-79f6-59db-af67-832d20c1c5bb', '66cba8a9-8597-53d6-94a8-5fdacb81ba7d', 'apertura_servicio', 'servicio', 'Apertura de servicio', 'Registro en el REPS de nuevos servicios incluyendo su complejidad, modalidad y capacidad instalada, según corresponda. Para los servicios que requieran visita previa, el registro de la novedad no implica su habilitación.', 'Resolución 3100 de 2019 (MinSalud)', 'Art. 12.3; Manual 10.3', 'págs. 6, 47-48', 'https://www.minsalud.gov.co/sites/rid/Lists/BibliotecaDigital/RIDE/DE/DIJ/resolucion-3100-de-2019.pdf', 'sugerir_alta_servicio', 16),
  ('649a8002-1b06-5e27-b58c-16e820c86d20', '66cba8a9-8597-53d6-94a8-5fdacb81ba7d', 'cierre_temporal_servicio', 'servicio', 'Cierre temporal de servicio', 'Registro en el REPS del cierre temporal de un servicio de salud habilitado, por un periodo máximo de un (1) año desde el reporte de esta novedad. A partir del registro de la novedad no puede continuar prestando el servicio de salud. El servicio puede ser reactivado por el prestador de servicios de salud antes de cumplirse el año, mediante el registro de la novedad de reactivación.', 'Resolución 3100 de 2019 (MinSalud)', 'Art. 12.3; Manual 10.3', 'págs. 6, 47-48', 'https://www.minsalud.gov.co/sites/rid/Lists/BibliotecaDigital/RIDE/DE/DIJ/resolucion-3100-de-2019.pdf', 'alerta_cierre_temporal', 17),
  ('47c1d0c5-61e6-5fc9-ac46-a7906e14df10', '66cba8a9-8597-53d6-94a8-5fdacb81ba7d', 'reactivacion_servicio', 'servicio', 'Reactivación de servicio', 'Registro en el REPS de la reactivación de un servicio de salud que se encuentra en cierre temporal.', 'Resolución 3100 de 2019 (MinSalud)', 'Art. 12.3; Manual 10.3', 'págs. 6, 47-48', 'https://www.minsalud.gov.co/sites/rid/Lists/BibliotecaDigital/RIDE/DE/DIJ/resolucion-3100-de-2019.pdf', null, 18),
  ('60f5c98c-70a4-5c61-ae98-575abd5e7681', '66cba8a9-8597-53d6-94a8-5fdacb81ba7d', 'cierre_definitivo_servicio', 'servicio', 'Cierre definitivo de servicio', 'Registro en el REPS del retiro de un servicio de salud, momento a partir del cual no puede continuar prestándolo. Aplica novedad de cierre de sede cuando se hace el cierre definitivo de la totalidad de los servicios de la sede.', 'Resolución 3100 de 2019 (MinSalud)', 'Art. 12.3; Manual 10.3', 'págs. 6, 47-48', 'https://www.minsalud.gov.co/sites/rid/Lists/BibliotecaDigital/RIDE/DE/DIJ/resolucion-3100-de-2019.pdf', null, 19),
  ('33bd4281-c96d-55b6-995a-6e1e8778b818', '66cba8a9-8597-53d6-94a8-5fdacb81ba7d', 'apertura_modalidad', 'servicio', 'Apertura de modalidad', 'Registro en el REPS de la apertura de una modalidad de prestación un servicio de salud.', 'Resolución 3100 de 2019 (MinSalud)', 'Art. 12.3; Manual 10.3', 'págs. 6, 47-48', 'https://www.minsalud.gov.co/sites/rid/Lists/BibliotecaDigital/RIDE/DE/DIJ/resolucion-3100-de-2019.pdf', null, 20),
  ('e6ad4e1d-696f-5557-bdc7-06b3a8f33ad6', '66cba8a9-8597-53d6-94a8-5fdacb81ba7d', 'cierre_modalidad', 'servicio', 'Cierre de modalidad', 'Registro en el REPS indicando el retiro de una modalidad de prestación de un servicio.', 'Resolución 3100 de 2019 (MinSalud)', 'Art. 12.3; Manual 10.3', 'págs. 6, 47-48', 'https://www.minsalud.gov.co/sites/rid/Lists/BibliotecaDigital/RIDE/DE/DIJ/resolucion-3100-de-2019.pdf', null, 21),
  ('d346aa0b-220a-5a8d-8c91-475a93a1174f', '66cba8a9-8597-53d6-94a8-5fdacb81ba7d', 'cambio_complejidad', 'servicio', 'Cambio de complejidad', 'Registro en el REPS de una nueva complejidad en la cual se prestará un servicio de salud. Para los servicios que requieran visita previa, el registro de la novedad no implica su habilitación.', 'Resolución 3100 de 2019 (MinSalud)', 'Art. 12.3; Manual 10.3', 'págs. 6, 47-48', 'https://www.minsalud.gov.co/sites/rid/Lists/BibliotecaDigital/RIDE/DE/DIJ/resolucion-3100-de-2019.pdf', null, 22),
  ('8aef84ab-a29f-57e7-a464-20002b336a63', '66cba8a9-8597-53d6-94a8-5fdacb81ba7d', 'cambio_horario_servicio', 'servicio', 'Cambio de horario de prestación de servicio', 'Registro en el REPS del nuevo horario en el cual se prestará un servicio de salud.', 'Resolución 3100 de 2019 (MinSalud)', 'Art. 12.3; Manual 10.3', 'págs. 6, 47-48', 'https://www.minsalud.gov.co/sites/rid/Lists/BibliotecaDigital/RIDE/DE/DIJ/resolucion-3100-de-2019.pdf', null, 23),
  ('59ec2cfa-b1ca-5566-932a-b45de3dccf7b', '66cba8a9-8597-53d6-94a8-5fdacb81ba7d', 'traslado_servicio', 'servicio', 'Traslado de servicio', 'Registro en el REPS de la nueva ubicación de un servicio de salud, diferente a la registrada inicialmente. Está novedad aplica para traslado de servicios entre sedes o dentro de una misma sede de un prestador de servicios de salud y no implica que el prestador deba realizar novedades de cierre definitivo y apertura del servicio.', 'Resolución 3100 de 2019 (MinSalud)', 'Art. 12.3; Manual 10.3', 'págs. 6, 47-48', 'https://www.minsalud.gov.co/sites/rid/Lists/BibliotecaDigital/RIDE/DE/DIJ/resolucion-3100-de-2019.pdf', null, 24),
