-- Obligaciones de reporte (17 de reportes.json + propias del prestador)


La regla de fecha incluye explícitamente a TEP (''… D3 y Transporte Especial de Pacientes''). Grupo B: periodicidad de su EAPB (sin regla: la clínica la registra a mano).

Regla literal: IPS no obligadas al Régimen de Contabilidad Pública – Grupos C2, D1, D2 y D3 y Transporte Especial de Pacientes: ''PERIODICIDAD: Semestral / FECHA DE CORTE: Junio 30 y Diciembre 31 / FECHA DEL REPORTE: Julio 20, Febrero 20 del año siguiente''. Grupo C1: ''Mensual / Último día de cada mes / 20 días calendario después de la fecha de corte. Para el cierre de año (diciembre 31), el reporte se hará hasta el 20 de febrero del año siguiente''. Grupo B: ''Corresponde a la periodicidad con la que reporta su Entidad Administradora de Planes de Beneficios (EAPB)''.'),
  ('e045fde2-97dd-518f-9dd3-a5ab5daca959', '66cba8a9-8597-53d6-94a8-5fdacb81ba7d', 'FT002', 'FT002 - Publicación Estados Financieros', 'Informa a la Supersalud la fecha, el medio y el sitio (URL) donde la entidad publicó sus estados financieros de fin de año. La publicación de los estados financieros con el dictamen del revisor fiscal (si aplica) debe hacerse a más tardar el 30 de abril en la página web de la entidad e incluir la expresión ''VIGILADO SUPERSALUD''.', 'supersalud', 'nRVCC (https://nrvcc.supersalud.gov.co/), XML', 'https://nrvcc.supersalud.gov.co/', 'Circular Externa Supersalud 016 de 2016 (adiciona a la Circular Única 047 de 2007)', '016', 'Numeral 4.4 (publicación) y Anexo Técnico ''Archivo Tipo FT002 – Publicación Estados Financieros''', 'https://normograma.supersalud.gov.co/compilacion/docs/circular_supersalud_0016_2016.htm', 'https://docs.supersalud.gov.co/PortalWeb/metodologias/OtrosDocumentosMetodologias/INSTRUCTIVO%20FT002.pdf', '2026-10-06', true, 'anual', array['ips']::text[], null, '{}'::text[], 'auto', false, array[30, 15, 7, 1, 0]::int[], true, 'Instructivo FT002 versión 05 publicado 05/08/2026: ''Todas las entidades ... Anual / Diciembre 31 / Abril 30''.

Regla literal: ''TIPO DE ENTIDAD A LA QUE APLICA: ... Instituciones Prestadoras de Servicios de Salud ... PERIODICIDAD: Anual / FECHA DEL REPORTE: Abril 30''. Publicación: ''La publicación debe realizarse a más tardar el 30 de abril después del cierre de año en la página web oficial de la entidad''.'),
  ('48ab42a3-09df-50fe-8216-f25bba5e7dad', '66cba8a9-8597-53d6-94a8-5fdacb81ba7d', 'FT003', 'FT003 - Cuentas por Cobrar – Deudores', 'Detalle de todas las cuentas por cobrar de la IPS por deudor, concepto y edad de la cartera. Debe cuadrar con el saldo del FT001.', 'supersalud', 'nRVCC (https://nrvcc.supersalud.gov.co/), XML firmado digitalmente', 'https://nrvcc.supersalud.gov.co/', 'Circular Externa Supersalud 2024151000000007-5', '2024151000000007-5', 'Instrucción TERCERA (modificación) e instrucción OCTAVA numeral 2 ''Anexo Técnico Archivo Tipo FT003''', 'https://docs.supersalud.gov.co/PortalWeb/Juridica/CircularesExterna/Circular%20externa%20n%C3%BAmero%202024151000000007-5%20de%202024.pdf', 'https://docs.supersalud.gov.co/PortalWeb/metodologias/OtrosDocumentosMetodologias/INSTRUCTIVO%20FT003.pdf', '2026-10-06', true, 'semestral', array['ips', 'transporte_especial']::text[], null, array['privada_o_mixta']::text[], 'auto', false, array[30, 15, 7, 1, 0]::int[], true, 'Instructivo FT003 versión 10 publicado 05/08/2026 coincide (C2, D1, D2, D3 semestral, julio 20 / febrero 20). Mismo riesgo de fecha en fin de semana/festivo que FT001.

Regla literal: Grupos C2, D1, D2 y D3 y TEP: ''PERIODICIDAD: Semestral / FECHA DE CORTE: Junio 30 y Diciembre 31 / FECHA DEL REPORTE: Julio 20, Febrero 20 del año siguiente''. Grupo C1: mensual, 20 días calendario después del corte (cierre: 20 de febrero). Grupo B: periodicidad de su EAPB.'),
  ('3a1393c4-e13c-56e9-9dfe-7253094d6fe3', '66cba8a9-8597-53d6-94a8-5fdacb81ba7d', 'FT004', 'FT004 - Detalle de Pasivos por Tercero (antes ''Cuentas por Pagar – Acreedores'')', 'Detalle de todas las cuentas por pagar de la IPS por acreedor, concepto y edad. Debe cuadrar con el FT001.', 'supersalud', 'nRVCC (https://nrvcc.supersalud.gov.co/), XML firmado digitalmente', 'https://nrvcc.supersalud.gov.co/', 'Circular Externa Supersalud 2024151000000007-5', '2024151000000007-5', 'Instrucciones TERCERA y CUARTA (cambio de nombre) e instrucción OCTAVA numeral 3', 'https://docs.supersalud.gov.co/PortalWeb/Juridica/CircularesExterna/Circular%20externa%20n%C3%BAmero%202024151000000007-5%20de%202024.pdf', 'https://docs.supersalud.gov.co/PortalWeb/metodologias/OtrosDocumentosMetodologias/INSTRUCTIVO%20FT004.pdf', '2026-10-06', true, 'semestral', array['ips', 'transporte_especial']::text[], null, array['privada_o_mixta']::text[], 'auto', false, array[30, 15, 7, 1, 0]::int[], true, 'Instructivo FT004 versión 09 publicado 05/08/2026 coincide.

Regla literal: Grupos C2, D1, D2 y D3 y TEP: ''Semestral / Junio 30 y Diciembre 31 / Julio 20, Febrero 20 del año siguiente''. C1 mensual (20 días calendario). B según su EAPB.'),
  ('48737f9d-35d1-53e5-9227-c20fa50e0c64', '66cba8a9-8597-53d6-94a8-5fdacb81ba7d', 'FT025', 'FT025 - Reporte de Facturación Radicada por IPS, Gestores Farmacéuticos y Operadores Logísticos de Tecnologías en Salud a entidades del aseguramiento en salud', 'Acumulado del año de la facturación radicada y lo recaudado frente a EPS, medicina prepagada, ARL, SOAT, entidades territoriales y demás aseguradores, por entidad, tipo de aseguramiento y modalidad de pago.', 'supersalud', 'nRVCC (https://nrvcc.supersalud.gov.co/), TXT/XML firmado digitalmente', 'https://nrvcc.supersalud.gov.co/', 'Circular Externa Supersalud 2024151000000007-5 (archivo creado por CE 014 de 2020)', '2024151000000007-5', 'Instrucciones TERCERA y SEXTA e instrucción OCTAVA numeral 7', 'https://docs.supersalud.gov.co/PortalWeb/Juridica/CircularesExterna/Circular%20externa%20n%C3%BAmero%202024151000000007-5%20de%202024.pdf', 'https://docs.supersalud.gov.co/PortalWeb/metodologias/OtrosDocumentosMetodologias/INSTRUCTIVO%20FT025.pdf', '2026-10-06', true, 'semestral', array['ips', 'transporte_especial']::text[], null, array['privada_o_mixta']::text[], 'auto', false, array[30, 15, 7, 1, 0]::int[], true, 'Instructivo FT025 versión 06 publicado 05/08/2026 coincide. PENDIENTE: confirmar con Supersalud o el nRVCC qué hace una IPS sin facturación a aseguradores.

Grupos B y C1: mensual (20 días calendario; cierre 20-feb).

Regla literal: Grupos C2, D1, D2 y D3 y TEP: ''Semestral / Junio 30 y Diciembre 31 / Julio 20, Febrero 20 del año siguiente.'' Grupos B y C1: mensual, 20 días calendario después del corte (cierre: 20 de febrero).'),
  ('2046e2e8-898e-5afe-a412-d3e75bd2f783', '66cba8a9-8597-53d6-94a8-5fdacb81ba7d', 'FT006', 'FT006 - Bancos y Carteras Colectivas', 'Detalle de cuentas bancarias y carteras colectivas de la entidad. Solo para IPS medianas/grandes (no aplica a D2 ni D3).', 'supersalud', 'nRVCC (https://nrvcc.supersalud.gov.co/), XML', 'https://nrvcc.supersalud.gov.co/', 'Circular Externa Supersalud 2024151000000007-5', '2024151000000007-5', 'Instrucción OCTAVA numeral 4', 'https://docs.supersalud.gov.co/PortalWeb/Juridica/CircularesExterna/Circular%20externa%20n%C3%BAmero%202024151000000007-5%20de%202024.pdf', 'https://docs.supersalud.gov.co/PortalWeb/metodologias/OtrosDocumentosMetodologias/INSTRUCTIVO%20FT006.pdf', '2026-10-06', true, 'semestral', array['ips']::text[], array['B', 'C1', 'C2', 'D1']::text[], array['privada_o_mixta']::text[], 'auto', false, array[30, 15, 7, 1, 0]::int[], true, 'Fechas listadas para C2/D1.

No aplica a D2 ni D3 (la prueba cruzada usa C2). C1 trimestral ''20 días calendario después del corte'' sin regla especial de cierre: el corte de diciembre vence el 20-ene (literal). Grupo B: según su EAPB (sin regla).

Regla literal: IPS Grupos C2, D1: ''Semestral / Junio 30 y Diciembre 31 / Julio 20, Febrero 20 del año siguiente''. C1: trimestral (marzo 31, junio 30, septiembre 30, diciembre 31), 20 días calendario después del corte. B: según su EAPB.'),
  ('6828f158-4caa-595e-8985-582377c5df4a', '66cba8a9-8597-53d6-94a8-5fdacb81ba7d', 'FT009', 'FT009 - Activos y Pasivos en Moneda Extranjera', 'Relación de activos y pasivos de la entidad denominados en moneda extranjera. Solo para IPS medianas/grandes (no aplica a D2 ni D3).', 'supersalud', 'nRVCC (https://nrvcc.supersalud.gov.co/), XML', 'https://nrvcc.supersalud.gov.co/', 'Circular Externa Supersalud 2024151000000007-5', '2024151000000007-5', 'Instrucción OCTAVA numeral 5', 'https://docs.supersalud.gov.co/PortalWeb/Juridica/CircularesExterna/Circular%20externa%20n%C3%BAmero%202024151000000007-5%20de%202024.pdf', 'https://docs.supersalud.gov.co/PortalWeb/metodologias/OtrosDocumentosMetodologias/INSTRUCTIVO%20FT009.pdf', '2026-10-06', true, 'semestral', array['ips']::text[], array['B', 'C1', 'C2', 'D1']::text[], array['privada_o_mixta']::text[], 'auto', false, array[30, 15, 7, 1, 0]::int[], true, 'La regla para C2/D1 se infirió del bloque de texto inmediatamente posterior en la circular (pág. 20-21), igual al de FT006; leído en el PDF, no en el instructivo.

No aplica a D2 ni D3 (la prueba cruzada usa C2). C1 trimestral con cierre 20-feb. Grupo B: según su EAPB (sin regla).

Regla literal: IPS Grupos C2, D1: semestral, cortes junio 30 y diciembre 31, reporte julio 20 y febrero 20. C1: trimestral, 20 días calendario después del corte (cierre: febrero 20). B: según su EAPB.'),
  ('a82771ab-f4c7-562c-a031-629c7d978182', '66cba8a9-8597-53d6-94a8-5fdacb81ba7d', 'FT018', 'FT018 - Datos para el Cálculo del Riesgo de Liquidez', 'Datos para que la Supersalud calcule el riesgo de liquidez de la entidad. Mensual y solo para IPS de grupos B, C1, C2 y D1.', 'supersalud', 'nRVCC (https://nrvcc.supersalud.gov.co/)', 'https://nrvcc.supersalud.gov.co/', 'Circular Externa Supersalud 2024151000000007-5 (archivo creado por CE 004 de 2018)', '2024151000000007-5', 'Instrucción QUINTA e instrucción OCTAVA numeral 6', 'https://docs.supersalud.gov.co/PortalWeb/Juridica/CircularesExterna/Circular%20externa%20n%C3%BAmero%202024151000000007-5%20de%202024.pdf', 'https://docs.supersalud.gov.co/PortalWeb/metodologias/OtrosDocumentosMetodologias/INSTRUCTIVO%20FT018.pdf', '2026-10-06', true, 'mensual', array['ips']::text[], array['B', 'C1', 'C2', 'D1']::text[], '{}'::text[], 'auto', false, array[30, 15, 7, 1, 0]::int[], true, 'Fechas = corte (último día del mes) + 20 días calendario. El corte del 31-dic-2026 se reporta hasta el 20-feb-2027, y el corte de enero de 2027 (31-ene + 20 = 20-feb) cae el mismo día; por eso no hay fecha el 20 de enero.

Públicas, privadas y mixtas de B, C1, C2 y D1. No aplica a D2 ni D3 (la prueba cruzada usa D1).

Regla literal: ''Instituciones Prestadoras de Servicios de Salud de los grupos B, C1, C2 y D1 públicos, privados y mixtos. PERIODICIDAD: Mensual / FECHA DE CORTE: Último día de cada mes / FECHA DEL REPORTE: 20 días calendario después de la fecha de corte. Para el cierre de año (diciembre 31), el reporte se hará hasta febrero 20 del año siguiente.'''),
  ('8f3d855d-721a-5a20-bd9d-37f5d85ad7d0', '66cba8a9-8597-53d6-94a8-5fdacb81ba7d', 'FP001-FP005', 'FP001 Conjunto completo de estados financieros y revelaciones; FP002 Certificación de estados financieros; FP003 Dictamen del revisor fiscal; FP004 Informe de gestión; FP005 Proyecto de distribución de utilidades', 'Envío anual en PDF de los estados financieros de fin de año con sus notas, la certificación firmada por representante legal y contador, el dictamen del revisor fiscal (si la entidad lo tiene), el informe de gestión y el proyecto de distribución de utilidades (si aplica).', 'supersalud', 'nRVCC (https://nrvcc.supersalud.gov.co/), archivos PDF (no escaneados)', 'https://nrvcc.supersalud.gov.co/', 'Circular Externa Supersalud 016 de 2016', '016', 'Anexo técnico ''Archivos tipo FP001 al FP005 – Archivos adicionales''', 'https://normograma.supersalud.gov.co/compilacion/docs/circular_supersalud_0016_2016.htm', 'https://normograma.supersalud.gov.co/compilacion/docs/circular_supersalud_0016_2016.htm', '2026-10-06', true, 'anual', array['ips', 'transporte_especial']::text[], null, '{}'::text[], 'auto', false, array[30, 15, 7, 1, 0]::int[], true, 'No existe instructivo separado publicado para FP001 (INSTRUCTIVO FP001.pdf devuelve 404); la estructura está en la propia circular. 2027-04-10 cae sábado.

FP003 solo con revisor fiscal y FP005 ''en caso de ser aplicable'': se siembra como una sola obligación (un solo envío anual); la UI lo explica.

Regla literal: ''TIPO DE ENTIDAD A LA QUE APLICA: ... Instituciones Prestadoras de Servicios de Salud, Transporte Especial de Pacientes y Generadores de Recursos. PERIODICIDAD: Anual / FECHA DE CORTE: Diciembre 31 / FECHA DEL REPORTE: Abril 10 del siguiente año''.'),
  ('543d5a5e-476f-5816-81c2-be784ddeb6dd', '66cba8a9-8597-53d6-94a8-5fdacb81ba7d', 'datos-generales-nrvcc', 'Actualización del módulo ''Datos Generales'' en nRVCC', 'Actualizar en el nRVCC los datos de contacto, la aceptación de notificación electrónica, directivos, junta, contador y revisor fiscal, comités, sedes y número de personal. Es obligatorio dos veces al año y además cada vez que algo cambie.', 'supersalud', 'nRVCC - módulo Datos Generales (https://nrvcc.supersalud.gov.co/)', 'https://nrvcc.supersalud.gov.co/', 'Circular Externa Supersalud 2024151000000013-5 (modifica parcialmente la Circular Única 047 de 2007)', '2024151000000013-5', 'Instrucción CUARTA', 'https://normograma.supersalud.gov.co/compilacion/docs/circular_supersalud_20241510000000135_2024.htm', 'https://normograma.supersalud.gov.co/compilacion/docs/circular_supersalud_20241510000000135_2024.htm', '2026-10-06', true, 'semestral', array['ips', 'transporte_especial']::text[], null, '{}'::text[], 'auto', false, array[30, 15, 7, 1, 0]::int[], true, 'La misma circular exige usar el logo ''Vigilado Supersalud'' en la publicidad (plazo 1-feb-2025). Responsabilidad indelegable del representante legal.

Todos los vigilados; no se verificó si el nRVCC tiene usuario para profesionales independientes (no se les asigna).

Regla literal: ''Las entidades vigiladas deberán realizar la actualización de la información solicitada en el módulo de datos generales de manera semestral, con corte a 30 de junio y 31 de diciembre de cada año. Las fechas límite de actualización son el 20 de julio y 20 de enero de cada anualidad respectivamente.'''),
  ('8f23aa81-7371-5c0f-9ecf-9e9ef888de63', '66cba8a9-8597-53d6-94a8-5fdacb81ba7d', 'ST002', 'ST002 - Aplicación del PAMEC', 'Reporte anual a la Supersalud del avance del Programa de Auditoría para el Mejoramiento de la Calidad (PAMEC): acciones de mejora programadas y ejecutadas y auditorías internas.', 'supersalud', 'nRVCC (https://nrvcc.supersalud.gov.co/)', 'https://nrvcc.supersalud.gov.co/', 'Circular Externa Supersalud 012 de 2016 (modifica la Circular Única 047 de 2007)', '012', 'Numeral 4.5.2 y Anexo Técnico ''Archivo Tipo ST002 – Aplicación del PAMEC''', 'https://normograma.supersalud.gov.co/compilacion/docs/circular_supersalud_0012_2016.htm', 'https://normograma.supersalud.gov.co/compilacion/docs/circular_supersalud_0012_2016.htm', '2026-10-06', true, 'anual', array['ips']::text[], array['B', 'C1', 'C2', 'D1', 'D2']::text[], '{}'::text[], 'por_confirmar', false, array[30, 15, 7, 1, 0]::int[], false, 'El texto de la norma está verificado, pero la vigencia del ST002 después de 2021 no está confirmada (no aparece en el módulo de archivos 2024-2026 revisado) y la referencia a grupos de una circular derogada genera ambigüedad. 2027-02-28 cae domingo.

Grupos de la CE 018/2015 (derogada); la correspondencia con los grupos de 2021 no se verificó → por_confirmar (no genera alerta roja hasta que el usuario la active).

Regla literal: ''TIPO DE ENTIDAD A LA QUE APLICA: Instituciones Prestadoras de Servicios públicas, privadas y mixtas de los grupos A, B, C1, C2, D1 y D2 (CE 018 de 2015) / Periodicidad: Anual / Fecha de Corte: diciembre 31 / Fecha de Reporte: febrero 28'''),
  ('41278338-2507-59ae-86c7-41c8aa4ed7bd', '66cba8a9-8597-53d6-94a8-5fdacb81ba7d', 'reps-autoevaluacion', 'Autoevaluación de las condiciones de habilitación y renovación de la inscripción en el REPS', 'Cada año el prestador verifica internamente que cumple los estándares de habilitación de cada servicio y declara ese cumplimiento en el REPS antes de que venza su inscripción. Si no lo hace, la inscripción o los servicios no autoevaluados quedan inactivos.', 'secretaria_salud', 'REPS - aplicativo de la secretaría de salud departamental/distrital (portal nacional: https://prestadores.minsalud.gov.co/habilitacion/)', 'https://prestadores.minsalud.gov.co/habilitacion/', 'Resolución 3100 de 2019 del Ministerio de Salud, modificada por las Res. 544 de 2023, 648 de 2023 y 465 de 2025', '3100', 'Art. 5 (modificado por art. 2 Res. 465/2025), num. 5.2 y 5.3; Art. 10 (vigencia de la inscripción); Art. 11 (consecuencias)', 'https://normograma.supersalud.gov.co/compilacion/docs/resolucion_minsaludps_3100_2019.htm', 'https://prestadores.minsalud.gov.co/habilitacion/', '2026-10-06', true, 'vencimiento_reps', array['ips', 'profesional_independiente', 'transporte_especial', 'objeto_social_diferente']::text[], null, '{}'::text[], 'auto', false, array[90, 60, 30, 15, 7, 1, 0]::int[], true, 'La Res. 1732 de 2026 (nuevo procedimiento de inscripción y habilitación) fue REVOCADA por la Res. 2080 del 8-sep-2026 (https://www.minsalud.gov.co/sites/rid/Lists/BibliotecaDigital/RIDE/DE/DIJ/resolucion-2080-de-2026.pdf) antes de publicarse en el Diario Oficial: sigue vigente la 3100/2019 con sus modificaciones. Art. 11: si no se autoevalúa, se inactiva la inscripción y para reactivarla se necesita visita (plazo de 6 meses para la secretaría). Sugerencia: el SaaS debe guardar por tenant la ''fecha de vencimiento de la inscripción REPS'' y alertar con 60/30/15 días de anticipación.

Regla literal: Art. 5: ''La autoevaluación es un requisito en los siguientes casos: ... 5.2 Durante el cuarto año de la vigencia de la inscripción inicial del prestador de servicios de salud y antes de su vencimiento. 5.3 Antes del vencimiento del término de renovación anual de la inscripción...''. Art. 10: ''Las renovaciones posteriores tendrán vigencia de un (1) año, previa autoevaluación de las condiciones de habilitación y declaración en el REPS, antes del vencimiento de cada año.'''),
  ('3215ec00-20dc-5bf8-819f-13c89799657c', '66cba8a9-8597-53d6-94a8-5fdacb81ba7d', 'reps-novedades', 'Reporte de novedades en el REPS', 'Todo cambio del prestador, de sus sedes, servicios o capacidad instalada (p.ej. apertura o cierre de sede o servicio, cambio de horario, de dirección, de representante legal, apertura de consultorios) se debe reportar como novedad ante la secretaría de salud.', 'secretaria_salud', 'REPS - formulario de novedades en la página de la secretaría de salud departamental/distrital', null, 'Resolución 3100 de 2019, art. 12 (modificado por art. 5 Res. 544 de 2023)', '3100', 'Art. 12, numerales 12.1 a 12.4', 'https://normograma.supersalud.gov.co/compilacion/docs/resolucion_minsaludps_3100_2019.htm', 'https://prestadores.minsalud.gov.co/habilitacion/', '2026-10-06', true, 'eventual', array['ips', 'profesional_independiente', 'transporte_especial', 'objeto_social_diferente']::text[], null, '{}'::text[], 'informativa', false, array[30, 15, 7, 1, 0]::int[], true, 'El Manual de Inscripción (anexo de la Res. 3100) puede fijar plazos previos para ciertas novedades (p.ej. apertura antes de prestar el servicio); no se transcribió aquí.

Regla literal: No se encontró un plazo en días en el art. 12: ''Los prestadores de servicios de salud están en la obligación de reportar las novedades que aquí se enuncian ante la respectiva secretaría de salud departamental o distrital ... diligenciando el formulario de reporte de novedades disponible en el aplicativo del REPS''. Algunas novedades requieren autoevaluación previa (art. 5.4).'),
  ('c119622d-d3b3-5300-a53a-856642969484', '66cba8a9-8597-53d6-94a8-5fdacb81ba7d', 'rips-fev', 'RIPS como soporte de la Factura Electrónica de Venta (FEV) en salud – Mecanismo Único de Validación', 'Cada factura electrónica de servicios de salud debe llevar su RIPS (detalle de usuario, procedimientos y valores), validado por MinSalud antes de radicarla al pagador. Plazo de radicación ante el pagador: 22 días hábiles desde que la DIAN valida la factura. Los servicios de cirugía estética no financiados con recursos públicos están excluidos.', 'minsalud', 'Mecanismo Único de Validación FEV-RIPS de MinSalud/SISPRO (RIPS en JSON + FEV en XML, genera el CUV)', null, 'Resolución 948 de 2026 del Ministerio de Salud (deroga Res. 2275 de 2023, 558 y 1884 de 2024)', '948', 'Arts. 2 (ámbito y parágrafo 1 de exclusiones), 7, 8 (obligatoriedad), 15 (radicación) y 23 (vigencia)', 'https://www.minsalud.gov.co/sites/rid/Lists/BibliotecaDigital/RIDE/DE/DIJ/resolucion-0948-de-2026.pdf', 'https://www.sispro.gov.co/central-financiamiento/Pages/facturacion-electronica.aspx', '2026-10-06', true, 'eventual', array['ips', 'profesional_independiente', 'transporte_especial', 'objeto_social_diferente']::text[], null, '{}'::text[], 'auto', true, array[30, 15, 7, 1, 0]::int[], true, 'Parágrafo transitorio: desde 1-jun-2026 rigen las reglas que pasan de notificación a rechazo; desde 1-jul-2026, los ajustes estructurales de versión del software. RIESGO para EWAH S.A.S.: la exclusión dice ''cirugía estética''; no se verificó si cubre la medicina estética no quirúrgica (toxina, rellenos, etc.). Decisión de interpretación para el usuario o su asesor. Texto también en Diario Oficial 53.495 (19-may-2026): https://sidn.ramajudicial.gov.co/SIDN//NORMATIVA/TEXTOS_COMPLETOS/8_RESOLUCIONES/RESOLUCIONES%202026/MSPS%20Resolucion%20000948%20de%202026.pdf

D6 (decisión del usuario): ''Aplica — confirma con tu asesor'' para todos; desactivable con justificación escrita y fecha de la consulta al asesor (la exclusión de la Res. 948/2026 art. 2 par. 1 para cirugía estética no financiada con recursos públicos no está verificada para medicina estética no quirúrgica).

Regla literal: Art. 8: ''Los facturadores electrónicos del sector salud deben reportar el RIPS de todas las atenciones de salud realizadas como soporte de la FEV en salud, con validación previa de la DIAN''. Art. 15: ''disponen de veintidós (22) días hábiles, contados a partir de la fecha de expedición de la factura electrónica de venta con validación previa de la DIAN, para la radicación ante las entidades responsables de pago o demás pagadores, de la factura y el RIPS aprobados por el mecanismo único de validación''. Objeto social diferente sin factura: ''mínimo de manera diaria y máximo de manera mensual, en este último caso dentro de los 5 primeros días calendario del mes siguiente''.'),
  ('18eecc48-0719-55b2-9802-a388a97a453a', '66cba8a9-8597-53d6-94a8-5fdacb81ba7d', 'res256-indicadores-calidad', 'Indicadores para el monitoreo de la calidad en salud (Sistema de Información para la Calidad) – Anexo Técnico 2', 'Reporte a MinSalud de los datos para los indicadores de calidad que corresponden al prestador (p.ej. oportunidad de citas y de atención por triage II en urgencias) según el Anexo Técnico 2 de la Res. 256/2016. Si no se reporta, MinSalud informa la novedad a la Supersalud.', 'minsalud', 'PISIS - Plataforma de Intercambio de Información de SISPRO (https://web.sispro.gov.co/), archivo plano TXT firmado digitalmente', 'https://web.sispro.gov.co/', 'Resolución 256 de 2016 del Ministerio de Salud, art. 6 con parágrafo adicionado por el art. 9 de la Res. 3539 de 2019 (art. 9 vigente; el resto de la 3539 fue derogado por la Res. 1632 de 2025)', '256', 'Arts. 2 (ámbito y exclusiones), 5 y 6 (parágrafo)', 'https://normograma.supersalud.gov.co/compilacion/docs/resolucion_minsaludps_0256_2016.htm', 'https://www.minsalud.gov.co/Normatividad_Nuevo/Resoluci%C3%B3n%200256%20de%202016.pdf', '2026-10-06', true, 'trimestral', array['ips', 'transporte_especial']::text[], null, '{}'::text[], 'auto', false, array[30, 15, 7, 1, 0]::int[], true, 'CONTRADICCIÓN INTERNA: el Anexo Técnico 2 todavía dice ''La periodicidad del envío de información es semestral ... enero a junio, hasta el 31 de julio; julio a diciembre, hasta 31 de enero''. El parágrafo posterior (2019) fija trimestral/30 días; se adopta el trimestral por ser norma posterior. No se verificó qué debe reportar una IPS cuyos servicios no generan ninguno de los registros del Anexo 2 (p.ej. una clínica estética sin consulta de medicina general).

Regla literal: Art. 6, parágrafo (Res. 3539/2019, art. 9): ''Las EPS ..., las Instituciones Prestadoras de Servicios de Salud y los Servicios de Transporte Especial de Pacientes, reportarán la información requerida al amparo de esta resolución, de forma trimestral, dentro de los treinta (30) días calendario siguientes a la terminación del respectivo trimestre. Vencido este plazo sin que se allegue dicha información, la correspondiente novedad se reportará a la Superintendencia Nacional de Salud''.'),
  ('e1234d4e-033e-52eb-9ccd-897bb15502b9', '66cba8a9-8597-53d6-94a8-5fdacb81ba7d', 'res202-pedt', 'Registro de actividades de Protección Específica y Detección Temprana (Res. 4505/2012 modificada por Res. 202/2021)', 'Reporte trimestral por persona de las actividades de promoción y mantenimiento de la salud y de la ruta materno-perinatal (vacunación, control prenatal, tamizajes, etc.). Solo es relevante si el prestador realiza esas actividades, normalmente por contrato con EPS.', 'minsalud', 'PISIS - SISPRO (https://web.sispro.gov.co/)', 'https://web.sispro.gov.co/', 'Resolución 202 de 2021 del Ministerio de Salud (modifica el art. 10 de la Res. 4505 de 2012)', '202', 'Art. 1 (nuevo art. 10 de la Res. 4505/2012)', 'https://normograma.supersalud.gov.co/compilacion/docs/resolucion_minsaludps_0202_2021.htm', 'https://normograma.supersalud.gov.co/compilacion/docs/resolucion_minsaludps_0202_2021.htm', '2026-10-06', true, 'trimestral', array['ips']::text[], null, array['pedt']::text[], 'auto', false, array[30, 15, 7, 1, 0]::int[], true, 'Probablemente NO aplica a una clínica estética privada sin contratos con EPS; incluido para otros tenants del SaaS. No se verificó si una IPS sin actividades PEDT debe enviar un reporte vacío.

Ventana de envío del día 18 al 25 del segundo mes tras el trimestre; la fecha límite es el 25.

Regla literal: ''... y las Instituciones Prestadoras de Salud (IPS), deben efectuar el reporte de la información trimestral, así: ... Primer día calendario del Trimestre / Último día calendario del trimestre / Día calendario 18 del segundo mes de finalizado el trimestre a reportar / Día calendario 25 del segundo mes de finalizado el trimestre a reportar''.'),
  ('c9fcdf06-5806-511c-a919-e83ab08133e6', '66cba8a9-8597-53d6-94a8-5fdacb81ba7d', 'sivigila', 'Notificación de eventos de interés en salud pública (SIVIGILA)', 'Si la secretaría de salud caracterizó al prestador como Unidad Primaria Generadora de Datos (UPGD), debe notificar los eventos de notificación obligatoria que detecte, en la periodicidad que fijan los protocolos del INS (semanal o inmediata según el evento), incluida la notificación ''negativa'' cuando no hay casos.', 'secretaria_salud', 'Aplicativo SIVIGILA del INS; la UPGD notifica a la secretaría de salud municipal/distrital (https://portalsivigila.ins.gov.co/)', 'https://portalsivigila.ins.gov.co/', 'Decreto 3518 de 2006 (compilado en el Decreto 780 de 2016, Parte 8, Título 8)', '3518', 'Arts. 13 (funciones de las UPGD), 17, 20 (notificación obligatoria) y 39', 'https://www.funcionpublica.gov.co/eva/gestornormativo/norma.php?i=21859', 'https://www.ins.gov.co/buscador-eventos/Paginas/Fichas-y-Protocolos.aspx', '2026-10-06', true, 'manual', array['ips', 'profesional_independiente']::text[], null, array['upgd']::text[], 'por_confirmar', false, array[30, 15, 7, 1, 0]::int[], false, 'Verificada la obligación en el decreto (funcionpublica). NO verificados: la periodicidad semanal exacta y el día de corte (Lineamientos Nacionales de Vigilancia 2026 del INS) ni si existe un evento específico para complicaciones de procedimientos estéticos. La URL de ''Lineamientos'' del INS respondió 404.

Notificación semanal/inmediata según protocolos del INS (no transcritos). ''semanal'' no está en el vocabulario de periodicidad: se siembra ''manual'' (la clínica registra cada envío).

Regla literal: Art. 20: ''deberán realizar la notificación de aquellos eventos de reporte obligatorio definidos en los modelos y protocolos de vigilancia, dentro de los términos de estructura de datos, responsabilidad, clasificación, periodicidad y destino señalados en los mismos''. El día de la semana y los plazos (semanal/inmediata) los fijan los protocolos y lineamientos anuales del INS: NO transcritos.'),
  ('4a2ab326-1f08-537a-a1b0-bcea343dcd59', '66cba8a9-8597-53d6-94a8-5fdacb81ba7d', 'telemedicina-mensual', 'Reporte mensual de atenciones en telemedicina (REPS)', 'Reportar dentro de los primeros cinco (5) días de cada mes las atenciones en modalidad de telemedicina (interactiva, no interactiva, telexperticia y telemonitoreo) en el enlace del REPS.', 'minsalud', 'REPS – enlace de reporte de telemedicina', 'https://prestadores.minsalud.gov.co/habilitacion/', 'Resolución 3100 de 2019, art. 21 parágrafo (adicionado por la Res. 1138 de 2022)', '3100', 'Art. 21 parágrafo', 'https://normograma.supersalud.gov.co/compilacion/docs/resolucion_minsaludps_3100_2019.htm', null, null, null, 'mensual', array['ips', 'profesional_independiente', 'transporte_especial', 'objeto_social_diferente']::text[], null, array['telemedicina']::text[], 'auto', false, array[30, 15, 7, 1, 0]::int[], true, null),
  ('8115093b-8339-56c9-8f19-54d97cc7221b', '66cba8a9-8597-53d6-94a8-5fdacb81ba7d', 'capacidad-instalada-diaria', 'Reporte diario de capacidad instalada (internación y urgencias)', 'Reportar diariamente en el REPS la capacidad instalada de los servicios del grupo de internación y del servicio de urgencias.', 'minsalud', 'REPS', 'https://prestadores.minsalud.gov.co/habilitacion/', 'Resolución 3100 de 2019, art. 21 parágrafo (adicionado por la Res. 1138 de 2022)', '3100', 'Art. 21 parágrafo', 'https://normograma.supersalud.gov.co/compilacion/docs/resolucion_minsaludps_3100_2019.htm', null, null, null, 'manual', array['ips', 'profesional_independiente', 'transporte_especial', 'objeto_social_diferente']::text[], null, array['internacion_o_urgencias']::text[], 'informativa', false, array[30, 15, 7, 1, 0]::int[], true, 'Diaria: no genera ocurrencias (sería una por día); se muestra como recordatorio informativo (§7 del requerimiento).'),
  ('6488192e-e589-536b-bd32-b502a8b8797f', '66cba8a9-8597-53d6-94a8-5fdacb81ba7d', 'grupo-supersalud-anual', 'Verificación anual del grupo de clasificación Supersalud', 'Verificar cada año el grupo de clasificación de la IPS (B, C1, C2, D1, D2, D3) con las cifras a 31 de diciembre de la vigencia anterior; de él dependen qué archivos tipo FT se reportan y con qué periodicidad.', 'supersalud', 'nRVCC', 'https://nrvcc.supersalud.gov.co/', 'Circular Externa Supersalud 20211700000005-5 de 2021, numeral 4.1', '20211700000005-5', 'Numeral 4.1', 'https://normograma.supersalud.gov.co/compilacion/docs/circular_supersalud_0005_2021.htm', null, null, null, 'manual', array['ips']::text[], null, '{}'::text[], 'informativa', false, array[30, 15, 7, 1, 0]::int[], false, 'La norma no fija una fecha límite para la verificación: no se inventa una. Se muestra como recordatorio anual que la clínica programa.'),
  ('abe6bcef-2f13-5a99-8dcc-dc565c9bca28', '66cba8a9-8597-53d6-94a8-5fdacb81ba7d', 'subsanacion-visita', 'Subsanación de hallazgos de la visita de verificación', 'Si la visita previa encuentra incumplimientos subsanables, el prestador tiene máximo 8 días hábiles desde el recibo de la comunicación para subsanarlos; si persisten, debe iniciar de nuevo el trámite.', 'secretaria_salud', 'Secretaría de salud departamental o distrital', null, 'Resolución 3100 de 2019, Manual num. 9.3.4.1', '3100', 'Art. 8.4; Art. 14; Manual 9.3.3.1, 9.3.4.1', 'https://www.minsalud.gov.co/sites/rid/Lists/BibliotecaDigital/RIDE/DE/DIJ/resolucion-3100-de-2019.pdf', null, null, null, 'eventual', array['ips', 'profesional_independiente', 'transporte_especial', 'objeto_social_diferente']::text[], null, '{}'::text[], 'auto', false, array[30, 15, 7, 1, 0]::int[], true, 'La fecha sale del hito ''visita realizada con subsanables'' + 8 días hábiles (usa la tabla festivos).'),
  ('2b9bb1ac-bdeb-5c5b-a997-e581412f106e', '66cba8a9-8597-53d6-94a8-5fdacb81ba7d', 'novedad-cierre-temporal', 'Vencimiento del cierre temporal de un servicio', 'El cierre temporal de un servicio dura máximo 1 año desde el reporte; si vencido no se reporta la reactivación, el servicio se inactiva en el REPS y para abrirlo hay que repetir el procedimiento de habilitación.', 'secretaria_salud', 'REPS – formulario de novedades', 'https://prestadores.minsalud.gov.co/habilitacion/', 'Resolución 544 de 2023, art. 6 (modifica el art. 13 de la Res. 3100 de 2019)', '544', 'Art. 6 (Art. 13) inc. 1 y 2', 'https://www.minsalud.gov.co/Normatividad_Nuevo/Resoluci%C3%B3n%20No.%20544%20de%202023.pdf', null, null, null, 'eventual', array['ips', 'profesional_independiente', 'transporte_especial', 'objeto_social_diferente']::text[], null, '{}'::text[], 'auto', false, array[30, 15, 7, 1, 0]::int[], true, 'La fecha sale de la novedad ''cierre temporal de servicio'': alerta a los 11 meses, límite al año.')
on conflict (id) do nothing;

-- Reglas de fecha (una fila = una ocurrencia por año; fecha límite LITERAL, D5)

on conflict (id) do nothing;

-- Novedades REPS

on conflict (id) do nothing;

-- Festivos de Colombia 2026–2028 (tabla global reutilizable)

on conflict (id) do nothing;

-- Aserciones finales de conteo

do $$
declare
  v int;
begin
  select count(*) into v from hab_tipos_prestador;
  if v <> 4 then
    raise exception 'Seed de habilitación: hab_tipos_prestador tiene % filas y se esperaban 4', v;
  end if;
  select count(*) into v from hab_documentos_catalogo where norma_id = '66cba8a9-8597-53d6-94a8-5fdacb81ba7d';
  if v <> 37 then
    raise exception 'Seed de habilitación: hab_documentos_catalogo tiene % filas y se esperaban 37', v;
  end if;
  select count(*) into v from hab_obligaciones_catalogo where norma_id = '66cba8a9-8597-53d6-94a8-5fdacb81ba7d';
  if v <> 22 then
    raise exception 'Seed de habilitación: hab_obligaciones_catalogo tiene % filas y se esperaban 22', v;
  end if;
  select count(*) into v from hab_obligacion_vencimientos where obligacion_id in (select id from hab_obligaciones_catalogo where norma_id = '66cba8a9-8597-53d6-94a8-5fdacb81ba7d');
  if v <> 113 then
    raise exception 'Seed de habilitación: hab_obligacion_vencimientos tiene % filas y se esperaban 113', v;
  end if;
  select count(*) into v from hab_novedades_catalogo where norma_id = '66cba8a9-8597-53d6-94a8-5fdacb81ba7d';
  if v <> 40 then
    raise exception 'Seed de habilitación: hab_novedades_catalogo tiene % filas y se esperaban 40', v;
  end if;
  select count(*) into v from festivos where pais_id = (select id from paises where codigo = 'CO') and fecha between '2026-01-01' and '2028-12-25';
  if v <> 54 then
    raise exception 'Seed de habilitación: festivos tiene % filas y se esperaban 54', v;
  end if;
end;
$$;

